var CF_TEXT_POOL_12KG=window.CF12KQDeploymentD1.take("CF_TEXT_POOL_12KG");
function cfUnpackStatic12KG(value){
 if(!value||typeof value!=='object')return value;
 if(!Array.isArray(value)&&Object.keys(value).length===1&&Object.prototype.hasOwnProperty.call(value,'$kg'))return CF_TEXT_POOL_12KG[value.$kg];
 Object.keys(value).forEach(function(k){value[k]=cfUnpackStatic12KG(value[k]);});return value;
}
function cfCopyStatic12KG(source,order,extra){
 function copy(v){if(!v||typeof v!=='object')return v;if(Array.isArray(v))return v.map(copy);var o={};Object.keys(v).forEach(function(k){o[k]=copy(v[k]);});return o;}
 var out={};order.forEach(function(k){out[k]=Object.prototype.hasOwnProperty.call(extra,k)?extra[k]:copy(source[k]);});return out;
}

