 var h2=new THREE.Mesh(cfSphereGeometry12JG(r,20,14),mat); h2.scale.x=0.55; h2.position.x=-len/2; g.add(h2);
 /* Head-to-shell seam rings, same reasoning as bVert above -- oriented across
    the horizontal axis since this vessel lies on its side. Bolt heads added
    directly to the local group (not the shared boltRing() helper, since this
    vessel's parts live in group-local coordinates, not global add()). */
 [len/2,-len/2].forEach(function(sx){
  var sr=new THREE.Mesh(cfTorusGeometry12JG(r*0.98,r*0.045,6,26),mFlange); sr.rotation.y=Math.PI/2; sr.position.set(sx,0,0); g.add(sr);
  for(var bi=0;bi<12;bi++){var a=(bi/12)*Math.PI*2; var bolt=new THREE.Mesh(cfCylinderGeometry12JG(r*0.044,r*0.044,r*0.05,6),mDark); bolt.position.set(sx,Math.cos(a)*r*0.98,Math.sin(a)*r*0.98); bolt.rotation.z=Math.PI/2; g.add(bolt);}
 });
 var leg1=new THREE.Mesh(cfBoxGeometry12JG(0.25,legH,0.9),mSteel); leg1.position.set(len*0.28,-legH/2,0); g.add(leg1);
 var leg2=new THREE.Mesh(cfBoxGeometry12JG(0.25,legH,0.9),mSteel); leg2.position.set(-len*0.28,-legH/2,0); g.add(leg2);
