 function put(g,mat,a,b,c,part,primary){var o=new THREE.Mesh(g,mat);o.position.set(x+a,b,z+c);o.userData.coldVisual12HY=part;o.userData.visualOnly=true;o.userData.dimensionAuthority='SCHEMATIC_VISUAL_DETAIL';o.userData.coldPrimary12HY=!!primary;add(o,k);parts.push(o);return o;}
 function box(w,h,d,a,b,c,mat,part,primary){return put(cfBoxGeometry12JG(w,h,d),mat,a,b,c,part,primary);}
