 function bar(a,b,r,mat,part){var A=V(a[0],a[1],a[2]),B=V(b[0],b[1],b[2]),v=B.clone().sub(A),len=v.length();if(len<1e-6)return null;var c=A.clone().add(B).multiplyScalar(.5);var o=put(cfCylinderGeometry12JG(r,r,len,8),mat,c.x,c.y,c.z,part);o.quaternion.setFromUnitVectors(V(0,1,0),v.normalize());return o;}
 function plaque(title,subtitle,w,h,a,b,c,rotation,small){
  var canvas=document.createElement('canvas');canvas.width=768;canvas.height=256;var ctx=canvas.getContext('2d');
  if(ctx){ctx.fillStyle='#132d40';ctx.fillRect(0,0,768,256);ctx.strokeStyle='#abc2d0';ctx.lineWidth=5;ctx.strokeRect(8,8,752,240);ctx.fillStyle='#edf4f7';ctx.textAlign='center';ctx.font='bold 76px Arial';ctx.fillText(title,384,101);ctx.fillStyle='#b7d1e0';ctx.font='bold 29px Arial';ctx.fillText(subtitle,384,164);ctx.font='20px Arial';ctx.fillText(small||'SCHEMATIC 3D DETAIL',384,219);}
  var tex=new THREE.CanvasTexture(canvas),mat=new THREE.MeshBasicMaterial({map:tex,side:THREE.DoubleSide});
  var p=put(new THREE.PlaneGeometry(w,h),mat,a,b,c,'equipment-plaque');p.rotation.y=rotation||0;p.userData.label=title+' | '+subtitle+' | '+(small||'SCHEMATIC 3D DETAIL');return p;
 }
 var record={key:k,parts:parts,modelEnvelope:null};CF_COLD_VISUALS_12HY.push(record);
 return {m:m,parts:parts,record:record,put:put,box:box,cyl:cyl,ring:ring,bar:bar,plaque:plaque};
