 K.record.modelEnvelope={kind:'existing-tower-envelope',height:h,radius:r,shellRadius:R,baseY:GY};
 pad(x,z,r*3.6,r*3.6);
 K.cyl(r*.95,r,3,0,1.4+GY,0,m.frame,'skirt','y',true);
 // Original cylindrical shell split into jacket courses without changing its envelope.
 var shellBottom=3+GY,shellH=h-4,courses=12,course=shellH/courses;
 for(var c=0;c<courses;c++){K.cyl(R,R,course,0,shellBottom+(c+.5)*course,0,c%2?m.jacket:m.light,'shell-course','y',true);}
 var top=K.put(cfSphereGeometry12JG(R,48,24),m.light,0,h-1.5+GY,0,'top-head',true);top.scale.y=.55;
 var bot=K.put(cfSphereGeometry12JG(r*.9,48,24),m.shade,0,2.5+GY,0,'bottom-head',true);bot.scale.y=.55;
 for(var c=0;c<=courses;c++){if(c===0||c===4||c===11)continue;K.ring(R+.009,.025,0,shellBottom+c*course,0,m.edge,'jacket-band','y');}
 // Surface seams are thin jacket details, not instrument tubing.
 [10,120,170,230,340].forEach(function(deg){var t=deg*Math.PI/180;var strip=K.box(.028,shellH-.08,.016,Math.cos(t)*(R+.007),shellBottom+shellH/2,Math.sin(t)*(R+.007),m.shade,'jacket-longitudinal-seam');strip.rotation.y=Math.PI/2-t;});
 K.ring(r*.96,.07,0,GY+.20,0,m.bolt,'base-flange','y');
 for(var i=0;i<16;i++){var a=i*Math.PI/8;K.cyl(.075,.075,.25,Math.cos(a)*r*.95,GY+.31,Math.sin(a)*r*.95,m.bolt,'skirt-anchor','y');}
 // Existing lower manway is detailed in-place; no new shell penetration is asserted.
 K.cyl(.35,.35,.12,-R,5+GY,0,m.edge,'manway-neck','x');
 K.cyl(.40,.40,.055,-R-.09,5+GY,0,m.bolt,'manway-cover','x');
 for(var i=0;i<10;i++){var a=i*Math.PI/5;K.cyl(.035,.035,.07,-R-.15,5+GY+Math.cos(a)*.32,Math.sin(a)*.32,m.frame,'manway-bolt','x');}
 // Replace floating disc platforms and the translucent ladder wedge. Existing
 // three elevations retained; fourth is a schematic top landing, not field data.
 var decks=[3+.35*(h-6)+GY,3+.55*(h-6)+GY,3+.75*(h-6)+GY,h-7+GY];
 K.record.platformElevations=decks.slice();
 var ri=R+.13,ro=R+2.0,theta=180*Math.PI/180,rad=R+.82,tx=-Math.sin(theta),tz=Math.cos(theta),ux=Math.cos(theta),uz=Math.sin(theta);
 K.record.ladderAzimuthDegrees=180;
 function point(radius,y,ang){return [Math.cos(ang)*radius,y,Math.sin(ang)*radius];}
 decks.forEach(function(y,deckIndex){var sectors=deckIndex===3?[[75,164]]:[[75,164],[196,240]];
  // Open radial grating planks with a deliberate ladder well (164-196 degrees).
  for(var deg=76;deg<=(deckIndex===3?164:238);deg+=3){if(deg>164&&deg<196)continue;var a=deg*Math.PI/180,rr=(ri+ro)/2;var p=K.box(.155,.09,ro-ri,rr*Math.cos(a),y,rr*Math.sin(a),m.edge,'platform-grating');p.rotation.y=Math.PI/2-a;}
  // Stiff edge stringers and continuous rails, split at the ladder opening.
  sectors.forEach(function(sector){
   for(var deg=sector[0];deg<sector[1];deg+=5){var a=deg*Math.PI/180,b=Math.min(deg+5,sector[1])*Math.PI/180;
    K.bar(point(ro,y-.07,a),point(ro,y-.07,b),.055,m.frame,'platform-edge');
    [1.4,2.8].forEach(function(dy){K.bar(point(ro,y+dy,a),point(ro,y+dy,b),.032,m.rail,'platform-guardrail');});
   }
   [sector[0],(sector[0]+sector[1])/2,sector[1]].forEach(function(deg){var a=deg*Math.PI/180;K.bar(point(ro,y-.04,a),point(ro,y+2.83,a),.045,m.frame,'platform-post');K.bar(point(R,y-1.05,a),point(ro-.05,y-.08,a),.055,m.frame,'platform-brace');});
   // Radial rails close the two outer ends, not the access opening.
   var a=(sector[0]===75?75:240)*Math.PI/180;
   [1.4,2.8].forEach(function(dy){K.bar(point(ri,y+dy,a),point(ro,y+dy,a),.032,m.rail,'platform-end-rail');});
  });
 });
 var low=GY+.2,high=decks[3]+3.0;
 [-.52,.52].forEach(function(s){K.bar([rad*ux+s*tx,low,rad*uz+s*tz],[rad*ux+s*tx,high,rad*uz+s*tz],.052,m.edge,'ladder-rail');});
 for(var y=GY+.75;y<decks[3]+.20;y+=1.10)K.bar([rad*ux-.55*tx,y,rad*uz-.55*tz],[rad*ux+.55*tx,y,rad*uz+.55*tz],.035,m.bolt,'ladder-rung');
 for(var y=GY+3;y<high-1;y+=8){[-.52,.52].forEach(function(s){K.bar([(Math.sqrt(R*R-s*s)-.02)*ux+s*tx,y,(Math.sqrt(R*R-s*s)-.02)*uz+s*tz],[rad*ux+s*tx,y,rad*uz+s*tz],.04,m.edge,'ladder-bracket');});}
