function cfUpdateHeaterVisuals12HX(dt){
 if(typeof PLANT==='undefined'||!PLANT||!PLANT.in)return;
 var v=PLANT.v||{},inp=PLANT.in;
 CF_HEATER_VISUALS_12HX.forEach(function(h){
  var regen=h.key==='h1711',firing=regen?(inp.regenHeaterRun!==false&&v.dehyPhase==='HEAT'&&Number(v.h_firing)>.5):(inp.heaterRun===true);
  if(PLANT.esd)firing=false;
  // H-7100 does not borrow H-1711's firing-rate signal. Its indicator uses its
  // existing heater-enable state only and does not assert a measured flame.
  var fraction=regen?Math.max(0,Math.min(1,Number(v.h_firing)/100)):.65;
  h.phase+=(Number(dt)||0);h.glow.visible=firing;h.simulatedFiring=firing;
  h.flameMaterial.opacity=firing?(.52+.36*fraction)*(.98+.02*Math.sin(h.phase*7)):0;
  h.indicatorMaterial.color.set(firing?0x39c78b:0x52606a);
 });
}
