  var footY=GY+.55;[-1,1].forEach(function(side){box(t.l*.72,.42,.34,t.dx,footY,side*.66,dark,t.name+'-mount-foot',false);box(t.l*.92,.18,.47,t.dx,GY+.31,side*.66,steel,t.name+'-mount-sole',false);[-1,1].forEach(function(s){cyl(.066,.066,.13,t.dx+s*t.l*.32,GY+.42,side*.66,bolt,t.name+'-mount-bolt','y',false);});});
