 // Perimeter steelwork and small fasteners remain within the original skid footprint.
 [-1,1].forEach(function(side){box(11.72,.15,.14,0,GY+.65,side*2.89,steel,'skid-edge',false);for(var i=0;i<6;i++)cyl(.065,.065,.075,-5.15+i*2.05,GY+.748,side*2.87,bolt,'skid-fastener','y',false);});
