/* ── flare stack with tip ── */
function bFlare(k,x,z,h){h=h||60; var GY=-1.9;
 pad(x,z,10,10);
 cylY(0.6,1.1,h,h/2+GY,mSteel,k,x,z);
 var tip=new THREE.Mesh(new THREE.ConeGeometry(0.9,2.5,14),mRed); tip.position.set(x,h+1.2+GY,z); add(tip,k);
 var flame=new THREE.Mesh(new THREE.ConeGeometry(0.7,3.5,10),new THREE.MeshBasicMaterial({color:0xff8c30,transparent:true,opacity:0.75})); flame.position.set(x,h+3.2+GY,z); add(flame,k);
 for(var g=0;g<3;g++){var guyR=h*0.5; var an=g/3*Math.PI*2; seg(new THREE.Vector3(x,h*0.65+GY,z),new THREE.Vector3(x+Math.cos(an)*guyR,GY,z+Math.sin(an)*guyR),0.04,mGrayP,k);}
 return {top:new THREE.Vector3(x,h+GY,z), bot:new THREE.Vector3(x,GY,z)};
}

/* ── ground pad sized to the real site footprint ── */
