var grassBig=new THREE.Mesh(new THREE.CircleGeometry(950,64),new THREE.MeshStandardMaterial({color:0x4f7a3d,roughness:0.95}));
grassBig.rotation.x=-Math.PI/2; grassBig.position.set(0,-2.05,-10); plant.add(grassBig);
/* subtle grass color variation ring for depth */
var grassRing2=new THREE.Mesh(new THREE.RingGeometry(300,950,64),new THREE.MeshStandardMaterial({color:0x5c8a48,roughness:0.95}));
grassRing2.rotation.x=-Math.PI/2; grassRing2.position.set(0,-2.04,-10); plant.add(grassRing2);
/* industrial gravel pad — circular, matches the security fence footprint */
var groundBig=new THREE.Mesh(new THREE.CircleGeometry(370,64),new THREE.MeshStandardMaterial({color:0x9d9481,roughness:0.98}));
groundBig.rotation.x=-Math.PI/2; groundBig.position.set(0,-2.0,-10); plant.add(groundBig);
var gridBig=new THREE.GridHelper(740,74,0x3a4048,0x30363d); gridBig.position.set(0,-1.99,-10); gridBig.material.opacity=0.28; gridBig.material.transparent=true; plant.add(gridBig);

/* ── place every equipment item; store its anchor for piping ── */
var ANCH={};
Object.keys(EQP).forEach(function(key){
 var e=EQP[key], x=e.x, z=e.z, s=e.s, a=null;
 /* 12GC: Reference-only records have no physical coordinates. Keep their
    knowledge records, but never construct NaN meshes or a default vessel. */
 if(!Number.isFinite(x)||!Number.isFinite(z)){ANCH[key]=null;return;}
 switch(e.t){
  case 'demeth':   a=bTower(key,x,z,88*s,2.1*s,mShell); break; /* 2x height per Ryan's request -- radius unchanged, nozzles stay offset from T.top.y so they move with it automatically */
  case 'tower':    a=bTower(key,x,z,22*s,1.7*s,mShell); break;
  case 'vert':     a=bVert(key,x,z,13*s,1.7*s,mShell); break;
  case 'horiz':    {var _hRotY=0,_hLiftY=0;
   if(key==='v1422'){ /* moved to the open ground directly north of T-1521 per Ryan --
      genuinely clear (everything else in the demeth cluster sits south of the tower),
      and close enough that the direct tower-bottoms liquid feed makes sense as a short
      run. Facing the tower again (clean 90 deg, not a diagonal) so the near/far end
      nozzle scheme below still means something. Platform elevation unchanged. */
    _hRotY=Math.PI/2; _hLiftY=13.3;
   }
   a=bHoriz(key,x,z,15*s,1.6*s,mShell,_hRotY,_hLiftY);} break;
  case 'filter':   a=bFilter(key,x,z,mGrayP); break;
  case 'filterh':  a=bHoriz(key,x,z,9*s,1.3*s,mGrayP); break; /* F-6800 only, per Ryan: this filter stands horizontally, not vertically like the other coalescing filters */
  case 'inletcomp':case 'rescomp':case 'ohcomp': a=bComp(key,x,z,mMach); break;
  case 'refcomp':  a=bRefComp(key,x,z); break;
  case 'expander': a=bExpander(key,x,z); break;
  case 'cooler':   a=bCooler(key,x,z,mAmber,key==='a1321'?3:2); break;
  case 'aircooler':a=bCooler(key,x,z,mAmber,3); break;
  case 'exch':     a=bHoriz(key,x,z,10*s,1.1*s,mSteel); break;
  case 'kettle':    a=bKettle(key,x,z,mSteel,0); break;
  case 'vrectexch':a=bVertRect(key,x,z,15*s,4*s,3*s,mSteel); break;
  case 'tank':     a=bTank(key,x,z,9*s,5.5*s,mShell); break;
  case 'building': a=bBuilding(key,x,z,32*s,22*s,15*s,mShell); break;
  case 'heater':   a=bHeater(key,x,z,mDark); break;
  case 'pump':     a=bPump(key,x,z,mMach); break;
  case 'flare':    a=bFlare(key,x,z,60); break;
  case 'cv': a=null; break; /* 12GD: tagged valves are installed inline after routing. */
  case 'psv':case 'skid':case 'marker':case 'site': a=null; break; /* reference/quick-jump coordinate only -- no independent geometry. Real PSVs on major vessels are already drawn by psvB() in the field-instrumentation pass, keyed to the vessel's own anchor; these EQP entries exist purely so Quick Jump / the Reference Library can fly the camera there. Before this fix, ALL 30 of them (26 auto-generated psv_KEY entries, one per major vessel, plus 4 standalone psv/psvC/psvV/psv1422/lube markers) fell through to the unhandled-type default below and each built a full-size phantom vertical VESSEL stacked exactly on top of its parent vessel -- almost certainly most of what "weird T-shaped vessels" was describing, and not limited to the one spot near the expander. 'site' (Pond Dock) had the same problem: a full vessel body where a dock reference point should have nothing. */
  default:         a=bVert(key,x,z,10,1.3,mShell);
 }
 ANCH[key]=a;
 var ly=(a&&a.top)?a.top.y+2.2:10;
 label(e.tag,x,ly,z,1.05,key);
});

/* ── mol-sieve desiccant bed internals — visible cross-hatch support screen + packed
   desiccant fill, matching the P&ID's internal bed symbol, seen through a translucent shell ── */
['f1412'].forEach(function(key){
 var a=ANCH[key]; if(!a)return; var x=EQP[key].x, z=EQP[key].z;
 var meshes=byKey[key]||[]; meshes.forEach(function(m){ if(m.material&&m.material.transparent!==undefined){ m.material=m.material.clone(); m.material.transparent=true; m.material.opacity=0.5; }});
 var y0=a.bot.y+1.5, y1=a.top.y-1.5, midY=(y0+y1)/2;
 for(var cx=-1;cx<=1;cx++){for(var cz=-1;cz<=1;cz++){ if(cx===0&&cz===0)continue;
  var cart=new THREE.Mesh(cfCylinderGeometry12JG(0.15,0.15,y1-y0,10),new THREE.MeshStandardMaterial({color:0xd8dde3,roughness:0.6}));
  cart.position.set(x+cx*0.35,midY,z+cz*0.35); add(cart,key);
 }}
});
/* F-1416 / F-1417: horizontal cartridge filter housings -- gas flows end-to-end, so
   the filter cartridges run lengthwise along the vessel's own axis, not vertically */
