/* BEGIN 12GU REFERENCE-ONLY NAMEPLATES
   An unplaced physical valve is a reference record, not a guessed mesh or a
   duplicate of its HMI / learned-document identity. No database writes occur. */
function cf3dEnsureReferenceValves12GU(){
 [['XV-1711A','cf3d_cv_xv1711a','H-1711 regeneration heater HEAT-path valve'],
  ['XV-1711B','cf3d_cv_xv1711b','H-1711 regeneration heater bypass / COOL-path valve']].forEach(function(def){
  var same=Object.keys(CF3D_DEVICE_RECORDS).filter(function(k){return cf3dDeviceNorm(CF3D_DEVICE_RECORDS[k].tag)===cf3dDeviceNorm(def[0]);});
  if(same.length)return; // Existing identity always wins; do not create another record.
  var r=cf3dRegisterDeviceRecord({key:def[1],tag:def[0],kind:'sequence',equipment:'H-1711',service:def[2],aliases:[def[0].toLowerCase().replace(/-/g,'')]},false);
  r.referenceRecordOnly=true;r.parentAssetId='h1711';
 });
}
cf3dEnsureReferenceValves12GU();
/* END 12GU REFERENCE-ONLY NAMEPLATES */
/* 12GW: no storage writes. A photo-backed record and a placed object are
 * independently checked; a parent Fly To never counts as valve placement. */
function cf3dNameplateCoverage12GW(){
 return Object.keys(CF3D_DEVICE_RECORDS).filter(function(k){return CF3D_DEVICE_RECORDS[k].photoIds.length>0;}).map(function(k){var r=CF3D_DEVICE_RECORDS[k],v=CF3D_CONTROL_VALVES.filter(function(x){return cf3dDeviceNorm(x.tag)===cf3dDeviceNorm(r.tag);});return {tag:r.tag,assetId:k,matchedObjects:v.length,installed:v.length===1&&!!v[0].installedSpool&&!!(byKey[k]&&byKey[k].some(function(m){return !!m.parent;})),referenceOnly:!!r.referenceRecordOnly};});
}
window.CF3DNameplateCoverage12GW=cf3dNameplateCoverage12GW;


function cf3dDeviceRecord(k){return CF3D_DEVICE_RECORDS[k]||CF3D_DEVICE_RECORDS[CF3D_DEVICE_ALIASES[k]]||null;}
function cf3dExactValveDocuments(r){
 if(!r||!r.tagConfirmed||typeof RYAN_CACHE==='undefined'||!RYAN_CACHE)return [];
 var targets=[r.tag].concat(r.aliases||[]).filter(function(t){return /^[A-Z][A-Z0-9]*-\d+[A-Z0-9-]*$/i.test(t);}).map(cf3dDeviceNorm),docs=Array.isArray(RYAN_CACHE.documents)?RYAN_CACHE.documents:[];
 return docs.filter(function(d){
  if(!d)return false;
  var b=d.referenceBinding||{},primary=d.primaryEquipmentId||b.primaryTag;
  if(primary)return targets.indexOf(cf3dDeviceNorm(primary))>=0;
  return Array.isArray(d.equipmentIds)&&d.equipmentIds.some(function(t){return targets.indexOf(cf3dDeviceNorm(t))>=0;});
 }).slice(0,10);
}
