 schedDbOpen(function(db){
  if(!db){if(cb)cb();return;}
  var tx=db.transaction('sched','readwrite');
  tx.objectStore('sched').put({id:'main',data:data,saved:Date.now()});
  tx.oncomplete=function(){if(cb)cb();};
 });
