var ATTACH_SEL={folder:'All Attachments',id:null,search:''},ATTACH_RETURN_TO_LIBRARY=false,ATTACH_BLOB_URL=null,ATTACH_SEARCH_TIMER=null;
function attachmentRecords(cb){assetMigrateLegacyRecords(function(){pdfDbAll(function(recs){cb(recs.filter(function(r){return assetRecordType(r)==='attachment';}).map(assetNormalizeRecord));});});}
