function ryanCoreStoreAll(storeName,items,cb){ryanDbOpen(function(db){libWriteStore(db,storeName,items||[],cb);});}
function ryanCoreLoadAll(storeName,cb){ryanDbOpen(function(db){libReadStore(db,storeName,cb);});}
function ryanBrainFallbackKey(storeName){return 'clearforkRyanBrain_'+storeName;}
function ryanBrainFallbackLoad(storeName){try{var a=JSON.parse(localStorage.getItem(ryanBrainFallbackKey(storeName))||'[]');return Array.isArray(a)?a:[];}catch(e){return [];}}
function ryanBrainFallbackStore(storeName,items){try{var a=ryanBrainFallbackLoad(storeName),by={};a.forEach(function(x){if(x&&x.id)by[x.id]=x;});(items||[]).forEach(function(x){if(x&&x.id)by[x.id]=x;});localStorage.setItem(ryanBrainFallbackKey(storeName),JSON.stringify(Object.keys(by).map(function(k){return by[k];})));return true;}catch(e){console.error('[Ryan Brain] localStorage fallback write failed',e);return false;}}
function ryanBrainStoreAll(storeName,items,cb){ryanBrainOpen(function(db){if(!db||!db.objectStoreNames.contains(storeName)){var ok=ryanBrainFallbackStore(storeName,items);if(cb)cb(ok);return;}try{var tx=db.transaction(storeName,'readwrite'),os=tx.objectStore(storeName);items.forEach(function(it){os.put(it);});tx.oncomplete=function(){ryanBrainFallbackStore(storeName,items);if(cb)cb(true);};tx.onerror=function(){var ok=ryanBrainFallbackStore(storeName,items);if(cb)cb(ok);};}catch(err){console.error('[Ryan Brain] write exception',err);var ok=ryanBrainFallbackStore(storeName,items);if(cb)cb(ok);}});}
function ryanBrainLoadAll(storeName,cb){var fallback=ryanBrainFallbackLoad(storeName);ryanBrainOpen(function(db){libReadStore(db,storeName,function(rows,ok){var by=Object.create(null);fallback.forEach(function(x){if(x&&x.id)by[x.id]=x;});rows.forEach(function(x){if(x&&x.id)by[x.id]=x;});cb(Object.keys(by).map(function(k){return by[k];}),ok);});});}
function ryanStoreAll(storeName,items,cb){if(storeName==='memories'||storeName==='suggestions'||storeName==='operatingProfiles')return ryanBrainStoreAll(storeName,items,cb);return ryanCoreStoreAll(storeName,items,cb);}
function ryanLoadAll(storeName,cb){if(storeName==='memories'||storeName==='suggestions'||storeName==='operatingProfiles')return ryanBrainLoadAll(storeName,cb);return ryanCoreLoadAll(storeName,cb);}
function ryanRefreshCache(cb){
 if(RYAN_REFRESH_JOB){if(cb)RYAN_REFRESH_JOB.callbacks.push(cb);return;}
 var job={callbacks:cb?[cb]:[],pending:7,done:false,values:{},failed:[],timer:null};RYAN_REFRESH_JOB=job;
 function finish(){if(job.done)return;job.done=true;clearTimeout(job.timer);if(RYAN_REFRESH_JOB===job)RYAN_REFRESH_JOB=null;Object.keys(job.values).forEach(function(k){RYAN_CACHE[k]=job.values[k];});RYAN_CACHE.ready=true;RYAN_CACHE_LAST_REFRESH=Date.now();libInvalidateLearnedCache();if(job.failed.length||job.pending)libStorageWarning('Some local records could not be refreshed. Showing the last loaded data; nothing was deleted.');job.callbacks.forEach(function(fn){try{fn();}catch(e){console.error('[Ryan cache view]',e);}});}
 function receive(name,rows,ok){if(job.done)return;if(ok!==false)job.values[name]=rows||[];else{job.failed.push(name);if(rows&&rows.length){var by=Object.create(null);(RYAN_CACHE[name]||[]).concat(rows).forEach(function(r){if(r&&r.id)by[r.id]=r;});job.values[name]=Object.keys(by).map(function(k){return by[k];});}}if(--job.pending===0)finish();}
 job.timer=setTimeout(finish,8000);
 ['documents','proposals','pmTemplates','training'].forEach(function(name){try{ryanCoreLoadAll(name,function(rows,ok){receive(name,rows,ok);});}catch(e){receive(name,[],false);}});
 ['suggestions','memories','operatingProfiles'].forEach(function(name){try{ryanBrainLoadAll(name,function(rows,ok){receive(name,rows,ok);});}catch(e){receive(name,[],false);}});
}
function ryanSaveSuggestion(text,focus,cost){
 var now=new Date();
 var item={id:'sug-'+now.getTime()+'-'+Math.floor(Math.random()*100000),createdAt:now.toISOString(),updatedAt:now.toISOString(),status:'new',focus:(focus||'Plant-wide').slice(0,180),text:String(text||'').slice(0,12000),cost:cost||null};
 ryanStoreAll('suggestions',[item],function(){ryanRefreshCache(function(){if(RYAN_AI_ACTIVE_TAB==='suggestions')askRyanRender();});});
}
function ryanSetSuggestionStatus(id,status){
 var it=(RYAN_CACHE.suggestions||[]).filter(function(x){return x.id===id;})[0]; if(!it)return;
 it.status=status;it.updatedAt=new Date().toISOString();
 ryanStoreAll('suggestions',[it],function(){ryanRefreshCache(function(){askRyanRender();});});
}
function ryanSuggestionLogHtml(){
 var list=(RYAN_CACHE.suggestions||[]).slice().sort(function(a,b){return String(b.createdAt).localeCompare(String(a.createdAt));});
 if(!list.length)return '<div style="margin-top:14px;border-top:1px solid #264733;padding-top:10px;color:#738b7a;font-size:11px;">No saved suggestions yet. Each Ryan Suggestions review will be saved here automatically.</div>';
 var counts={new:0,reviewed:0,implemented:0,dismissed:0};list.forEach(function(x){counts[x.status]=(counts[x.status]||0)+1;});
 var h='<div style="margin-top:14px;border-top:1px solid #264733;padding-top:10px;"><div style="font-weight:700;color:#c7f5d4;margin-bottom:5px;">Persistent Suggestions Log</div><div style="font-size:10.5px;color:#71877a;margin-bottom:8px;">NEW '+counts.new+' · REVIEWED '+counts.reviewed+' · IMPLEMENTED '+counts.implemented+' · DISMISSED '+counts.dismissed+' — stored on this device in Ryan Core.</div>';
 h+=list.slice(0,30).map(function(x){var st=(x.status||'new').toUpperCase();var badge=x.status==='implemented'?'#245f39':(x.status==='dismissed'?'#5a2a2a':(x.status==='reviewed'?'#4a4220':'#24506a'));return '<div style="background:#111b15;border:1px solid #294735;border-radius:6px;padding:8px 9px;margin-bottom:7px;"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center;"><div><span style="background:'+badge+';color:#fff;border-radius:3px;padding:1px 6px;font-size:9px;font-weight:700;">'+st+'</span> <span style="font-size:10px;color:#8aa090;">'+new Date(x.createdAt).toLocaleString()+' · '+(x.focus||'Plant-wide').replace(/</g,'&lt;')+'</span></div><div style="display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end;"><button data-sugstatus="reviewed" data-sugid="'+x.id+'" style="font-size:9px;padding:2px 5px;">Reviewed</button><button data-sugstatus="implemented" data-sugid="'+x.id+'" style="font-size:9px;padding:2px 5px;">Implemented</button><button data-sugstatus="dismissed" data-sugid="'+x.id+'" style="font-size:9px;padding:2px 5px;">Dismiss</button></div></div><div style="white-space:pre-wrap;color:#d7e8dc;font-size:11.5px;line-height:1.42;margin-top:6px;max-height:190px;overflow:auto;">'+String(x.text||'').replace(/</g,'&lt;')+'</div></div>';}).join('');
 return h+'</div>';
}
function ryanHash(str){ /* simple deterministic string hash -- not cryptographic, just enough for local dedup, matching the spirit (not the literal SHA-256 code) of the server version's dedup-by-content-identity rule */
 var h=0; for(var i=0;i<str.length;i++){h=((h<<5)-h+str.charCodeAt(i))|0;}
 return 'h'+(h>>>0).toString(16);
}
/* === Ryan Persistent Brain / Memory ===
   Direct operator teaching is remembered immediately as OPERATOR_PROVIDED.
   Ryan self-learning is retained as PROVISIONAL until reviewed, so inference
   never silently becomes a verified plant fact. */
function ryanMemoryId(prefix){return (prefix||'mem')+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);}
function ryanSaveMemory(text,opts,cb){
 opts=opts||{}; text=String(text||'').trim(); if(!text){if(cb)cb(null);return;}
 var item={id:ryanMemoryId('mem'),text:text.slice(0,4000),title:String(opts.title||'Operator-taught note').slice(0,180),
  sourceType:opts.sourceType||'OPERATOR_PROVIDED',trust:opts.trust||'OPERATOR_PROVIDED',status:opts.status||'active',
  tags:Array.isArray(opts.tags)?opts.tags.slice(0,20):[],equipmentIds:Array.isArray(opts.equipmentIds)?opts.equipmentIds.slice(0,30):[],system:String(opts.system||'').slice(0,120),
  createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),timesRecalled:0,lastRecalledAt:null,
  provenance:opts.provenance||'Teach Ryan written note'};
 ryanStoreAll('memories',[item],function(ok){if(ok===false){if(cb)cb(null);return;}ryanRefreshCache(function(){if(cb)cb(item);});});
}
function ryanSetMemoryStatus(id,status){var m=(RYAN_CACHE.memories||[]).filter(function(x){return x.id===id;})[0];if(!m)return;m.status=status;m.updatedAt=new Date().toISOString();ryanStoreAll('memories',[m],function(){ryanRefreshCache(function(){askRyanRender();});});}
function ryanDeleteMemory(id){try{var a=ryanBrainFallbackLoad('memories').filter(function(x){return x.id!==id;});localStorage.setItem(ryanBrainFallbackKey('memories'),JSON.stringify(a));}catch(_e){}ryanBrainOpen(function(db){if(!db||!db.objectStoreNames.contains('memories')){ryanRefreshCache(function(){askRyanRender();});return;}try{var tx=db.transaction('memories','readwrite');tx.objectStore('memories').delete(id);tx.oncomplete=function(){ryanRefreshCache(function(){askRyanRender();});};}catch(e){ryanRefreshCache(function(){askRyanRender();});}});}
function ryanMemoryMatches(q,m){var toks=String(q||'').toLowerCase().split(/[^a-z0-9-]+/).filter(function(t){return t.length>2;});if(!toks.length)return true;var h=(m.title+' '+m.text+' '+(m.tags||[]).join(' ')+' '+(m.equipmentIds||[]).join(' ')).toLowerCase();return toks.some(function(t){return h.indexOf(t)>=0;});}
function ryanMemoryText(q){
 var active=(RYAN_CACHE.memories||[]).filter(function(m){return m.status==='active'||m.status==='provisional';});
 var matched=active.filter(function(m){return ryanMemoryMatches(q,m);}); if(!matched.length&&active.length)matched=active.slice(-20);
 matched=matched.slice(-50); if(!matched.length)return '(no persistent Ryan memories yet)';
 return matched.map(function(m){return '['+m.trust+' | '+m.status+' | '+m.sourceType+'] '+m.title+': '+m.text+(m.equipmentIds&&m.equipmentIds.length?' | Equipment: '+m.equipmentIds.join(', '):'');}).join('\n');
}

/* === Ryan Operational Experience Brain ===
   Shift/2-hour/12-hour report patterns and selected historian windows are retained as
   source-labelled operating episodes. They help Ryan compare the current plant with past
   situations, but never become verified limits, P&ID facts, or proof of causation. */
function ryanOpArray(v,limit,itemLimit){var a=Array.isArray(v)?v:[];return a.slice(0,limit||20).map(function(x){return String(x||'').trim().slice(0,itemLimit||700);}).filter(function(x){return x;});}
function ryanOpIso(v){if(!v)return '';try{var d=new Date(v);return isNaN(d.getTime())?String(v).slice(0,80):d.toISOString();}catch(_e){return String(v).slice(0,80);}}
function ryanNormalizeOperatingProfile(raw,meta){raw=raw||{};meta=meta||{};var title=String(raw.title||meta.title||'Operating experience').trim().slice(0,220),summary=String(raw.summary||meta.summary||'').trim().slice(0,5000),sourceType=String(meta.sourceType||raw.sourceType||'HISTORICAL_OPERATING_EVIDENCE').slice(0,80),sourceId=String(meta.sourceId||raw.sourceId||'').slice(0,240),sourceLabel=String(meta.sourceLabel||raw.sourceLabel||'').slice(0,240),startTime=ryanOpIso(raw.startTime||meta.startTime),endTime=ryanOpIso(raw.endTime||meta.endTime),stable=[sourceType,sourceId,title,startTime,endTime].join('|'),id='op-'+ryanHash(stable),old=(RYAN_CACHE.operatingProfiles||[]).filter(function(x){return x.id===id;})[0],now=new Date().toISOString();return {id:id,kind:String(meta.kind||raw.kind||'OPERATING_EPISODE').slice(0,80),title:title||'Operating experience',summary:summary,system:String(raw.system||meta.system||'').slice(0,160),equipmentIds:ryanOpArray(raw.equipmentIds||meta.equipmentIds,40,80),tags:ryanOpArray(raw.tags||meta.tags,60,100),conditions:ryanOpArray(raw.conditions,30,900),responses:ryanOpArray(raw.responses,30,900),relationships:ryanOpArray(raw.relationships,30,1000),normalRanges:ryanOpArray(raw.normalRanges,30,700),outliers:ryanOpArray(raw.outliers,20,800),troubleshootingCues:ryanOpArray(raw.troubleshootingCues,30,1000),doNotTreatAs:ryanOpArray(raw.doNotTreatAs,20,700),confidence:String(raw.confidence||meta.confidence||'medium').toLowerCase().slice(0,20),evidenceCount:Math.max(0,Number(raw.evidenceCount||meta.evidenceCount||0)||0),sourceType:sourceType,sourceId:sourceId,sourceLabel:sourceLabel,trust:String(meta.trust||raw.trust||'HISTORICAL_OPERATING_EVIDENCE').slice(0,80),verificationStatus:String(meta.verificationStatus||raw.verificationStatus||'HISTORICAL_OPERATING_EVIDENCE').slice(0,100),status:String(raw.status||meta.status||'active').slice(0,30),startTime:startTime,endTime:endTime,provenance:String(meta.provenance||raw.provenance||sourceLabel||sourceType).slice(0,600),autoInstalled:!!meta.autoInstalled,createdAt:old&&old.createdAt?old.createdAt:now,updatedAt:now};}
function ryanSaveOperatingProfiles(records,meta,cb){var src=Array.isArray(records)?records:[],items=src.map(function(r){return ryanNormalizeOperatingProfile(r,meta);}).filter(function(r){return r.summary||r.conditions.length||r.responses.length||r.relationships.length||r.normalRanges.length;});if(!items.length){if(cb)cb([],false);return;}ryanStoreAll('operatingProfiles',items,function(ok){if(ok===false){if(cb)cb([],false);return;}ryanRefreshCache(function(){if(cb)cb(items,true);});});}
function ryanDeleteOperatingProfile(id){try{var a=ryanBrainFallbackLoad('operatingProfiles').filter(function(x){return x.id!==id;});localStorage.setItem(ryanBrainFallbackKey('operatingProfiles'),JSON.stringify(a));}catch(_e){}ryanBrainOpen(function(db){if(!db||!db.objectStoreNames.contains('operatingProfiles')){ryanRefreshCache(function(){askRyanRender();});return;}try{var tx=db.transaction('operatingProfiles','readwrite');tx.objectStore('operatingProfiles').delete(id);tx.oncomplete=function(){ryanRefreshCache(function(){askRyanRender();});};tx.onerror=function(){ryanRefreshCache(function(){askRyanRender();});};}catch(e){ryanRefreshCache(function(){askRyanRender();});}});}
function ryanOperatingProfileScore(q,p){var toks=String(q||'').toLowerCase().split(/[^a-z0-9-]+/).filter(function(t){return t.length>2&&!CF_STOPWORDS[t];}),head=(String(p.title||'')+' '+String(p.system||'')+' '+(p.equipmentIds||[]).join(' ')+' '+(p.tags||[]).join(' ')+' '+String(p.sourceLabel||'')).toLowerCase(),all=(head+' '+String(p.summary||'')+' '+(p.conditions||[]).join(' ')+' '+(p.responses||[]).join(' ')+' '+(p.relationships||[]).join(' ')+' '+(p.troubleshootingCues||[]).join(' ')).toLowerCase(),score=0;toks.forEach(function(t){if(head.indexOf(t)>=0)score+=6;else if(all.indexOf(t)>=0)score+=2;});if(/report|shift|histor|normal|usual|previous|past/i.test(q)&&/REPORT/.test(p.sourceType||''))score+=3;if(/trend|changed|first|drift|oscillat/i.test(q)&&/TREND/.test(p.sourceType||''))score+=3;return score;}
function ryanOperatingExperienceText(q,maxChars){var active=(RYAN_CACHE.operatingProfiles||[]).filter(function(p){return !p.status||p.status==='active'||p.status==='provisional';}),ranked=active.map(function(p){return {p:p,score:ryanOperatingProfileScore(q,p)};}).sort(function(a,b){return b.score-a.score||String(b.p.updatedAt||b.p.createdAt||'').localeCompare(String(a.p.updatedAt||a.p.createdAt||''));}),chosen=ranked.filter(function(x){return x.score>0;}).slice(0,18);if(!chosen.length)chosen=ranked.slice(0,6);if(!chosen.length)return '(no stored operating experience yet)';var lines=['SOURCE-LABELLED HISTORICAL OPERATING EXPERIENCE — comparison/troubleshooting evidence only; LIVE state and verified limits remain authoritative.'];chosen.forEach(function(x){var p=x.p,window=(p.startTime||p.endTime)?((p.startTime||'?')+' to '+(p.endTime||'?')):'time window not supplied';lines.push('\n['+(p.sourceType||'HISTORICAL')+' | '+(p.trust||'HISTORICAL_OPERATING_EVIDENCE')+' | '+String(p.confidence||'medium').toUpperCase()+' | evidence '+(p.evidenceCount||'?')+'] '+p.title);lines.push('Source: '+(p.sourceLabel||p.provenance||'stored operating experience')+' | Window: '+window);if(p.summary)lines.push('Summary: '+p.summary);if(p.conditions&&p.conditions.length)lines.push('Observed conditions: '+p.conditions.join(' | '));if(p.responses&&p.responses.length)lines.push('Observed responses: '+p.responses.join(' | '));if(p.relationships&&p.relationships.length)lines.push('Relationship candidates (not automatic proof): '+p.relationships.join(' | '));if(p.normalRanges&&p.normalRanges.length)lines.push('Historical comparison ranges: '+p.normalRanges.join(' | '));if(p.outliers&&p.outliers.length)lines.push('Outliers/suspect data: '+p.outliers.join(' | '));if(p.troubleshootingCues&&p.troubleshootingCues.length)lines.push('Troubleshooting cues: '+p.troubleshootingCues.join(' | '));if(p.doNotTreatAs&&p.doNotTreatAs.length)lines.push('Do not treat as: '+p.doNotTreatAs.join(' | '));});return lines.join('\n').slice(0,maxChars||14000);}
function ryanOperatingExperiencePanelHtml(){var list=(RYAN_CACHE.operatingProfiles||[]).slice().sort(function(a,b){return String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||''));}),reports=list.filter(function(x){return /REPORT/.test(x.sourceType||'');}).length,trends=list.filter(function(x){return /TREND/.test(x.sourceType||'');}).length,h='<div style="background:#10242b;border:1px solid #326276;border-radius:7px;padding:11px 12px;"><div style="font-weight:700;color:#c9f7ff;">📚 Ryan Operational Experience</div><div style="font-size:11px;color:#8fb0bf;line-height:1.45;margin-top:4px;">Shift/2-hour/12-hour report patterns and historian windows stored here are automatically retrieved for later Clear Fork troubleshooting. Real report evidence stays separate from simulator trend evidence; neither becomes a trip limit or proof of causation.</div><div style="font-size:10.5px;color:#6f8b98;margin-top:6px;">'+list.length+' record(s): '+reports+' report-derived · '+trends+' trend-derived</div><button id="ryanLearn12hNow" style="margin-top:8px;background:#173a40;border:1px solid #3f7f89;color:#c9f7ff;border-radius:4px;padding:6px 11px;font-weight:700;cursor:pointer;">🧠 Install latest plant-wide 12h trends</button></div>';if(!list.length)return h+'<div style="color:#718491;font-size:11px;margin-top:10px;">No operating episodes installed yet. Analyze an archived shift report or open a 12h/24h/72h trend window.</div>';h+=list.slice(0,100).map(function(p){var src=/REPORT/.test(p.sourceType||'')?'REAL REPORT':'SIM TREND',c=src==='REAL REPORT'?'#8ee3a5':'#8fcfff',window=(p.startTime||p.endTime)?('<div style="font-size:9.5px;color:#68818f;">'+ryanEscape((p.startTime||'?')+' → '+(p.endTime||'?'))+'</div>'):'';return '<div style="background:#101a20;border:1px solid #2a4652;border-radius:6px;padding:8px 10px;margin-top:7px;"><div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start;"><div><span style="font-size:9px;font-weight:800;color:'+c+';">'+src+' · '+ryanEscape(String(p.confidence||'medium').toUpperCase())+'</span><div style="font-size:12px;color:#e3f1f6;font-weight:700;margin-top:2px;">'+ryanEscape(p.title||'Operating experience')+'</div>'+window+'</div><button data-opdelete="'+p.id+'" style="font-size:9px;padding:2px 6px;min-height:24px;">Delete</button></div><div style="font-size:10.8px;color:#b9cad1;white-space:pre-wrap;line-height:1.4;margin-top:5px;">'+ryanEscape(String(p.summary||'').slice(0,1200))+'</div><div style="font-size:9.5px;color:#6f8792;margin-top:4px;">Source: '+ryanEscape(p.sourceLabel||p.provenance||p.sourceType||'')+' · evidence '+ryanEscape(String(p.evidenceCount||'?'))+'</div></div>';}).join('');return h;}

