function ryanDescriptionItemType(text,primaryTag){var t=String(text||''),patterns=[[/fuel\s*gas\s+pressure\s+control\s+valve/i,'Fuel Gas Pressure Control Valve'],[/pressure\s+control\s+valve/i,'Pressure Control Valve'],[/temperature\s+control\s+valve/i,'Temperature Control Valve'],[/level\s+control\s+valve/i,'Level Control Valve'],[/flow\s+control\s+valve/i,'Flow Control Valve'],[/shutdown\s+valve/i,'Shutdown Valve'],[/block\s+valve/i,'Block Valve'],[/control\s+valve/i,'Control Valve'],[/pressure\s+(?:transmitter|indicator)/i,'Pressure Transmitter / Indicator'],[/temperature\s+(?:transmitter|element|indicator)/i,'Temperature Instrument'],[/flow\s+(?:transmitter|meter|indicator)/i,'Flow Instrument'],[/level\s+(?:transmitter|indicator|switch)/i,'Level Instrument'],[/data\s*plate|name\s*plate/i,'Equipment Data Plate']];for(var i=0;i<patterns.length;i++)if(patterns[i][0].test(t))return patterns[i][1];var map={PCV:'Pressure Control Valve',PVC:'Pressure Control Valve',PV:'Pressure Valve',PIC:'Pressure Indicating Controller',PIT:'Pressure Indicating Transmitter',PT:'Pressure Transmitter',TCV:'Temperature Control Valve',TIC:'Temperature Indicating Controller',LCV:'Level Control Valve',LIC:'Level Indicating Controller',FCV:'Flow Control Valve',FIC:'Flow Indicating Controller',XV:'Automated Block Valve',ESD:'Emergency Shutdown Device',PSV:'Pressure Safety Valve',FIT:'Flow Indicating Transmitter',FT:'Flow Transmitter',TE:'Temperature Element',LT:'Level Transmitter'};return map[ryanTagPrefix(primaryTag)]||'Learned Plant Device';}
