function doAskRyanSearch(){
 var inp=document.getElementById('askRyanQ'),el=document.getElementById('askRyanAns');if(!inp||!el)return;
 var q=inp.value||'',results=[];try{results=cmdRyanSearch(q)||[];}catch(err){console.error('[Ask Ryan] search failed',err);el.innerHTML='<div style="color:#ffb0b0;">Ask Ryan search error: '+String(err.message||err).replace(/</g,'&lt;')+'</div>';return;}
 LAST_RYAN_RESULTS=results; LAST_RYAN_Q=q;
 if(!results.length){el.innerHTML='<div style="color:#8a97a4;font-style:italic;">No Reference Library or approved Ryan Core entry matched that \u2014 try different words, or check the \ud83d\udcda Reference Library directly. This is not a "no such thing exists," just "nothing matched those words yet." Ryan AI above will still answer using general knowledge if you ask it, and will say plainly that nothing matched in this file.</div>';return;}
 /* Lead with a direct ANSWER built from the single best-matching fact (not
    the whole document it came from), then list the rest as supporting/
    related entries. Still 100% deterministic keyword extraction over
    human-approved text -- nothing here is generated, every word shown is
    copied verbatim from the Reference Library or an approved Ryan Core
    fact, so a citation is always real and exact. */
 var top=results[0];
 var topAnswer=(top.bestBullets&&top.bestBullets.length)?top.bestBullets.map(function(b){return b.text;}).join(' '):(top.info.d||[])[0]||top.info.t;
 var html='<div style="background:#0f2a1c;border:1px solid #2a6a3a;border-radius:6px;padding:10px 12px;margin-bottom:10px;">'+
  '<div style="font-size:9.5px;font-weight:700;color:#7fe0a0;letter-spacing:.5px;margin-bottom:4px;">ANSWER (deterministic \u2014 verbatim from this file, not AI-generated)</div>'+
  '<div style="font-size:13px;color:#eef2f7;line-height:1.45;">'+topAnswer+'</div>'+
  '<div style="font-size:10.5px;color:#8a97a4;margin-top:6px;">Source: '+top.info.t+'</div>'+
  (top.source==='library'?'<button data-cmdgoto="'+top.k+'" style="margin-top:6px;background:#243140;border:1px solid #3a4a5c;color:#cfe6ff;border-radius:3px;padding:2px 8px;cursor:pointer;font:700 10.5px inherit;">See full entry in Reference Library</button>':'')+
  '</div>';
 var rest=results.slice(1);
 if(rest.length){
  html+='<div style="font-size:10px;color:#6a7684;margin:8px 0 4px;">Other matching entries:</div>';
  html+=rest.map(function(r){return '<div style="background:#141a22;border:1px solid '+(r.source==='ryancore'?'#2a4a3a':'#2a3542')+';border-radius:6px;padding:8px 10px;margin-bottom:6px;">'+(r.source==='ryancore'?'<span style="background:#175c2a;color:#9ff0b6;font-size:9.5px;font-weight:700;border-radius:3px;padding:1px 6px;margin-right:6px;">RYAN CORE</span>':'')+'<span style="font-weight:700;color:#cfe6ff;font-size:12.5px;">'+r.info.t+'</span><div style="font-size:11.5px;color:#9fb0c0;margin-top:3px;">'+((r.bestBullets&&r.bestBullets.length)?r.bestBullets.map(function(b){return b.text;}).join(' \u00b7 '):(r.info.d||[]).slice(0,2).join(' \u00b7 '))+'</div>'+(r.source==='library'?'<button data-cmdgoto="'+r.k+'" style="margin-top:5px;background:#243140;border:1px solid #3a4a5c;color:#cfe6ff;border-radius:3px;padding:2px 8px;cursor:pointer;font:700 10.5px inherit;">Open in Reference Library</button>':'')+'</div>';}).join('');
 }
 el.innerHTML=html;
 el.querySelectorAll('[data-cmdgoto]').forEach(function(b){b.addEventListener('click',function(){
  var k=b.getAttribute('data-cmdgoto');closeAskRyan();openLibrary();libSel.key=k;
  for(var ci=0;ci<LIB_CATS.length;ci++){if(LIB_CATS[ci][1].indexOf(k)!==-1){libSel.cat=ci;break;}}
  libRenderCats();libRenderList();libRenderDetail();
 });});
}

var RYAN_LOTO_DOCS=[];
try{RYAN_LOTO_DOCS=JSON.parse(localStorage.getItem('ryanLotoDocs')||'[]');if(!Array.isArray(RYAN_LOTO_DOCS))RYAN_LOTO_DOCS=[];}catch(_e){RYAN_LOTO_DOCS=[];}
function ryanEscape(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function ryanSaveLotoDoc(doc){
 if(!doc)return null;
 var rec={id:'loto-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),createdAt:new Date().toISOString(),doc:doc};
 RYAN_LOTO_DOCS.unshift(rec);RYAN_LOTO_DOCS=RYAN_LOTO_DOCS.slice(0,30);
 try{localStorage.setItem('ryanLotoDocs',JSON.stringify(RYAN_LOTO_DOCS));}catch(_e){}
 return rec;
}
function ryanLotoList(items,empty){return (items&&items.length)?'<ol style="margin:5px 0 8px 20px;padding:0;">'+items.map(function(x){return '<li style="margin:4px 0;">'+ryanEscape(x)+'</li>';}).join('')+'</ol>':'<div style="color:#81909e;font-style:italic;margin:4px 0 8px;">'+ryanEscape(empty||'None source-backed.')+'</div>';}
function ryanLotoMarkerRows(items,type){
 if(!items||!items.length)return '<div style="color:#81909e;font-style:italic;">No source-backed '+type+' markers returned.</div>';
 return items.map(function(x){var pend=/PENDING/i.test((x.tag||'')+' '+(x.verification||''));return '<div style="display:grid;grid-template-columns:110px 1fr 145px;gap:7px;align-items:start;border-bottom:1px solid #303842;padding:6px 2px;">'+
  '<div style="font-family:Consolas,monospace;font-weight:700;color:'+(pend?'#ffd38a':'#dff3ff')+';">'+ryanEscape(x.tag||'PENDING VERIFICATION')+'</div><div><b>'+ryanEscape(x.action||'')+'</b><div style="font-size:10.5px;color:#a9b4bf;">'+ryanEscape(x.purpose||'')+'</div></div><div style="font-size:10px;color:#91a2b1;">'+ryanEscape(x.sourceDrawing||'')+'<br>'+ryanEscape(x.verification||'')+'</div></div>';}).join('');
}
function ryanLotoSchematic(doc){
 var colors={isolation:'#ffb347',blowdown:'#7ed6ff',psv:'#ff7f7f'};
 var all=[];(doc.isolationPoints||[]).forEach(function(x){all.push({x:x,t:'ISOLATION',c:colors.isolation});});(doc.blowdownPoints||[]).forEach(function(x){all.push({x:x,t:'BLOWDOWN',c:colors.blowdown});});(doc.psvMarkers||[]).forEach(function(x){all.push({x:x,t:'PSV / RELIEF',c:colors.psv});});
 var nodes=all.length?all.map(function(m,i){return '<div style="border:2px solid '+m.c+';background:#10161d;border-radius:5px;padding:7px;min-width:145px;max-width:230px;flex:1;"><div style="font-size:9px;font-weight:800;color:'+m.c+';">'+m.t+'</div><div style="font-family:Consolas,monospace;font-weight:800;margin:2px 0;color:#eef5fb;">'+ryanEscape(m.x.tag||'PENDING VERIFICATION')+'</div><div style="font-size:10px;color:#aeb9c4;">'+ryanEscape(m.x.purpose||m.x.action||'')+'</div></div>';}).join('<div style="align-self:center;color:#677787;font-size:18px;">→</div>'):'<div style="color:#81909e;">No exact source-backed markers were available. Field/P&ID verification is required before establishing a boundary.</div>';
 return '<div style="border:1px solid #394654;border-radius:6px;padding:10px;background:#0b1015;"><div style="font-size:10px;color:#8fa1b3;margin-bottom:7px;">SCHEMATIC P&ID MARKUP — Ryan-generated visualization of source-backed markers. This is not an engineering redline and does not replace the source drawing.</div><div style="display:flex;gap:7px;align-items:stretch;overflow-x:auto;padding-bottom:4px;">'+nodes+'</div></div>';
}
function ryanOpenLotoDoc(id){
 var rec=RYAN_LOTO_DOCS.filter(function(x){return x.id===id;})[0];if(!rec)return;var d=rec.doc||{};
 var old=document.getElementById('ryanLotoViewer');if(old)old.remove();
 var el=document.createElement('div');el.id='ryanLotoViewer';el.style.cssText='position:fixed;inset:0;z-index:990;background:rgba(3,6,10,.96);overflow:auto;padding:18px;';
 el.innerHTML='<div style="max-width:1050px;margin:auto;background:#111820;border:1px solid #46586a;border-radius:8px;color:#dce6ee;font:12.5px/1.5 -apple-system,Segoe UI,Arial,sans-serif;box-shadow:0 14px 50px #000;padding:18px;">'+
 '<div style="display:flex;justify-content:space-between;gap:10px;align-items:start;"><div><div style="font-size:19px;font-weight:800;color:#fff;">'+ryanEscape(d.title||'Ryan Draft LOTO / Work Plan')+'</div><div style="color:#ffb1a8;font-weight:800;margin-top:3px;">DRAFT — NOT APPROVED — FIELD VERIFICATION REQUIRED</div><div style="font-size:10px;color:#7f91a2;">Created '+ryanEscape(new Date(rec.createdAt).toLocaleString())+'</div></div><button data-close-loto="1" style="background:#7a2929;border:1px solid #b14a4a;color:#fff;border-radius:4px;padding:7px 13px;font-weight:700;cursor:pointer;">Close</button></div>'+ 
 '<div style="margin-top:14px;background:#1b2026;border-left:4px solid #ffb347;padding:9px 11px;"><b>Scope:</b> '+ryanEscape(d.scope||'')+'<br><b>Work boundary:</b> '+ryanEscape(d.workBoundary||'PENDING VERIFICATION')+'<br><b>Equipment:</b> '+ryanEscape((d.equipment||[]).join(', ')||'PENDING VERIFICATION')+'<br><b>Source drawings:</b> '+ryanEscape((d.sourceDrawings||[]).join(', ')||'PENDING VERIFICATION')+'<br><b>Execution blocked:</b> '+(d.executionBlocked?'YES — unresolved boundary/source issue':'NO — still NOT APPROVED and field verification remains required')+'</div>'+
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Source evidence / continuations</h3><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;"><div>'+ryanLotoList(d.sourceEvidence,'No source-evidence list returned.')+'</div><div>'+ryanLotoList(d.continuationDrawings,'No continuation list returned.')+'</div></div>'+
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Energy-path trace</h3>'+ryanLotoList(d.energyPathTrace,'No energy-path trace returned.')+
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Work plan</h3>'+ryanLotoList(d.workPlanSteps,'No steps returned.')+
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Energy sources / hazards</h3><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;"><div>'+ryanLotoList(d.energySources,'No source-backed energy list.')+'</div><div>'+ryanLotoList(d.hazards,'No source-backed hazards listed.')+'</div></div>'+ 
 '<h3 style="color:#ffcf9f;margin-bottom:5px;">Isolation / blowdown / PSV markup</h3>'+ryanLotoSchematic(d)+
 '<div style="display:grid;grid-template-columns:1fr;gap:10px;margin-top:10px;"><div><b style="color:#ffcf9f;">Isolation points</b>'+ryanLotoMarkerRows(d.isolationPoints,'isolation')+'</div><div><b style="color:#9fe7ff;">Blowdown / bleed points</b>'+ryanLotoMarkerRows(d.blowdownPoints,'blowdown')+'</div><div><b style="color:#ffaaaa;">PSVs / relief protection</b>'+ryanLotoMarkerRows(d.psvMarkers,'PSV')+'</div></div>'+ 
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Field verification checklist</h3>'+ryanLotoList(d.verificationChecklist,'Field verification checklist not returned.')+
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Zero-energy criteria</h3>'+ryanLotoList(d.zeroEnergyCriteria,'Zero-energy criteria not returned.')+
 '<h3 style="color:#ffd38a;margin-bottom:3px;">Conflicts / ambiguities / approval holds</h3><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;"><div>'+ryanLotoList(d.conflictsAndAmbiguities,'No conflicts returned; field verification is still mandatory.')+'</div><div>'+ryanLotoList(d.approvalRequirements,'Site approval requirements not returned.')+'</div></div>'+
 '<h3 style="color:#bfe0ff;margin-bottom:3px;">Restoration / return to service</h3>'+ryanLotoList(d.restorationSteps,'Restoration steps require site procedure/field verification.')+
 '<h3 style="color:#ffd38a;margin-bottom:3px;">Missing information / holds</h3>'+ryanLotoList(d.missingInformation,'No gaps reported by Ryan; field verification is still mandatory.')+
 '<div style="margin-top:14px;background:#3a1717;border:2px solid #a84848;color:#ffd4d4;border-radius:6px;padding:12px;font-weight:800;text-align:center;font-size:14px;">NOT APPROVED — FIELD VERIFICATION REQUIRED</div></div>';
 document.body.appendChild(el);el.querySelector('[data-close-loto]').addEventListener('click',function(){el.remove();});
}
function ryanLotoCard(rec){var d=rec.doc||{};return '<div data-open-loto="'+ryanEscape(rec.id)+'" style="cursor:pointer;background:#2a2010;border:1px solid #8a6532;border-radius:7px;padding:10px 12px;margin:7px 0;"><div style="font-size:9px;color:#ffcf9f;font-weight:800;">📋 RYAN LOTO / WORK PLAN — DRAFT</div><div style="font-size:13px;color:#fff;font-weight:800;margin-top:3px;">'+ryanEscape(d.title||'Draft LOTO / Work Plan')+'</div><div style="font-size:10.5px;color:#d7c5a8;margin-top:3px;">'+ryanEscape(d.scope||'')+'</div><div style="font-size:10px;color:#ffb0a8;margin-top:5px;font-weight:700;">Click to open document • NOT APPROVED — FIELD VERIFICATION REQUIRED</div></div>';}

