  '<button data-ryantab="experience" style="background:'+(experienceOn?'#173a40':'#141a22')+';border:1px solid '+(experienceOn?'#3f7f89':'#2a3542')+';border-bottom:none;color:'+(experienceOn?'#c9f7ff':'#8a97a4')+';border-radius:5px 5px 0 0;padding:7px 13px;cursor:pointer;font:700 11.5px inherit;">📚 Operating Experience</button>'+
  '</div>';
 var panel='';
