function ryanShiftReportToText(rec){
 return new Promise(function(resolve,reject){
  try{
   var name=String(rec&&rec.name||'report'),isXlsx=/\.xlsx$/i.test(name)||/spreadsheetml/i.test(String(rec&&rec.mediaType||''));
   if(isXlsx){
    if(typeof XLSX==='undefined'){reject(new Error('Excel parser did not load. Refresh the page with internet access and retry.'));return;}
    var wb=XLSX.read(ryanDataUrlToArrayBuffer(rec.dataUrl),{type:'array',cellDates:true});
    var chunks=[];wb.SheetNames.forEach(function(sn){var ws=wb.Sheets[sn];var csv=XLSX.utils.sheet_to_csv(ws,{FS:'\t',RS:'\n',blankrows:false});chunks.push('SHEET: '+sn+'\n'+csv);});
    resolve(chunks.join('\n\n').slice(0,60000));return;
   }
   var raw=String(rec&&rec.dataUrl||''),comma=raw.indexOf(','),meta=raw.slice(0,comma),b64=raw.slice(comma+1),txt='';
   if(/;base64/i.test(meta)){var bin=atob(b64),bytes=new Uint8Array(bin.length);for(var j=0;j<bin.length;j++)bytes[j]=bin.charCodeAt(j);txt=new TextDecoder('utf-8').decode(bytes);}else txt=decodeURIComponent(b64||'');
   resolve(txt.slice(0,60000));
  }catch(e){reject(e);}
 });
}
