function ryanLiveStateSummary(){
 /* Ryan-only readout of existing simulator state. This does NOT change plant
    physics, controls, alarms, trips, permissives, or operator inputs; it only
    serializes what the simulator already knows so the SME backend can reason
    about the same state the operator is seeing. */
 var h=computePlantHealth();
 var lines=['Plant Health: '+h.score.toFixed(0)+' ('+h.label+')', 'Facility ESD active: '+(!!PLANT.esd), 'Plant operating mode: '+(PLANT.mode||'unknown')];
 h.concerns.forEach(function(c){if(c[0]!=='NONE')lines.push('Concern ['+c[0]+']: '+c[1]);});
 lines.push('--- ROTATING EQUIPMENT ---');
 Object.keys(PLANT.cmp||{}).forEach(function(k){var c=PLANT.cmp[k]||{};lines.push((c.name||k)+': '+(c.run?'RUNNING':'STOPPED')+', step '+(c.step==null?'?':c.step)+'/'+(c.maxstep==null?'?':c.maxstep)+', suction '+fmtRyanNum(c.suc)+' psig, discharge '+fmtRyanNum(c.dis)+' psig, flow '+fmtRyanNum(c.flow)+', oilP '+fmtRyanNum(c.oilP)+' psig, oilT '+fmtRyanNum(c.oilT)+' F, dischargeT '+fmtRyanNum(c.discT)+' F, RPM '+fmtRyanNum(c.rpm));});
 lines.push('--- CONTROL LOOPS / BOARD VALUES ---');
 Object.keys(PLANT.L||{}).forEach(function(k){var l=PLANT.L[k]||{};lines.push(k+': PV '+fmtRyanNum(l.pv)+' '+(l.u||'')+', SP '+fmtRyanNum(l.sp)+' '+(l.u||'')+', OUT '+fmtRyanNum(l.out)+'%, MODE '+(l.man?'MANUAL':'AUTO'));});
 lines.push('--- VALVE / DISCRETE STATES ---');
 Object.keys(PLANT.valves||{}).forEach(function(k){var v=PLANT.valves[k];lines.push(k+': '+(typeof v==='number'?(v>=0&&v<=1?(v?'OPEN':'CLOSED'):fmtRyanNum(v)+'%'):String(v)));});
 if(typeof FILTER_RULES!=='undefined'){lines.push('--- FILTER HEALTH ---');Object.keys(FILTER_RULES).forEach(function(k){var r=FILTER_RULES[k];lines.push(r.name+': '+filterDP(k).toFixed(2)+' '+r.unit+' | '+filterStatus(k)+(r.change!=null?' | change '+r.change:'')+(r.trip!=null?' | trip '+r.trip:''));});}
 if(SCEN&&SCEN.log&&SCEN.log.length){lines.push('--- RECENT / ACTIVE ALARM LOG ---');SCEN.log.slice(0,12).forEach(function(a){lines.push((a&&a.m)||String(a));});}
 return lines.join('\n');
}
function fmtRyanNum(v){return (typeof v==='number'&&isFinite(v))?(Math.round(v*100)/100):((v==null)?'n/a':String(v));}

/* ===== Ryan Plant State Engine =====
   Read-only intelligence layer. Evaluates the simulator's EXISTING interlock
   functions against the same PLANT state used by the control boards. It never
   changes an input, output, trip, permissive, valve, controller, or scenario. */
function ryanPlantStateEngine(){
 var snap={generatedAt:new Date().toISOString(),mode:PLANT.mode||'unknown',esd:!!PLANT.esd,screen:TITLES[eqtCur]||eqtCur||'unknown',health:null,equipment:[],loops:[],valves:[],interlocks:{total:0,healthy:0,failed:0,errors:0,requiresVerification:0,failures:[],evaluationErrors:[],verificationGaps:[]},alarms:[],scenario:null,expander:null,refrigeration:null};
 try{var h=computePlantHealth();snap.health={score:h.score,label:h.label,concerns:(h.concerns||[]).filter(function(c){return c&&c[0]!=='NONE';})};}catch(e){snap.health={error:e.message};}
 Object.keys(PLANT.cmp||{}).forEach(function(k){var c=PLANT.cmp[k]||{};snap.equipment.push({key:k,tag:c.name||k,running:!!c.run,step:c.step,maxStep:c.maxstep,suction:c.suc,discharge:c.dis,flow:c.flow,oilPressure:c.oilP,oilTemp:c.oilT,dischargeTemp:c.discT,rpm:c.rpm});});
 Object.keys(PLANT.L||{}).forEach(function(k){var l=PLANT.L[k]||{};snap.loops.push({tag:k,pv:l.pv,sp:l.sp,out:l.out,unit:l.u||'',mode:l.man?'MANUAL':'AUTO'});});
 Object.keys(PLANT.valves||{}).forEach(function(k){snap.valves.push({tag:k,value:PLANT.valves[k]});});
 if(typeof INTERLOCK_DEFS!=='undefined')Object.keys(INTERLOCK_DEFS).forEach(function(key){var def=INTERLOCK_DEFS[key]||{},items=def.items||[];items.forEach(function(it){snap.interlocks.total++;var desc=String(it.desc||''),rec={interlock:def.title||key,tag:it.tag||'',description:desc};if(/requires verification|pending verification|never been confirmed|not yet backed|not yet confirmed/i.test(desc)){snap.interlocks.requiresVerification++;snap.interlocks.verificationGaps.push(rec);}try{var ok=(typeof it.ok==='function')?!!it.ok(PLANT.v||{},PLANT.L||{}):null;if(ok===true)snap.interlocks.healthy++;else if(ok===false){snap.interlocks.failed++;snap.interlocks.failures.push(rec);}else{snap.interlocks.errors++;snap.interlocks.evaluationErrors.push(Object.assign({reason:'No evaluable status'},rec));}}catch(e){snap.interlocks.errors++;snap.interlocks.evaluationErrors.push(Object.assign({reason:e.message},rec));}});});
 if(typeof SCEN!=='undefined'&&SCEN){snap.scenario={active:SCEN.active||null,elapsed:SCEN.t||0,auto:!!SCEN.auto};if(SCEN.log)snap.alarms=SCEN.log.slice(0,20).map(function(a){return {message:(a&&a.m)||String(a),time:(a&&a.t)||null};});}
 if(typeof EXP!=='undefined'&&EXP)snap.expander={running:!!EXP.run,igv:EXP.igv,trip:EXP.trip||null,remote:!!EXP.remote,localDemand:EXP.localDemand,boardManual:!!PLANT.L.PIC1521DEX.man,boardDemand:PLANT.L.PIC1521DEX.out,expanderSP:PLANT.L.PIC1521DEX.sp,jtSP:PLANT.L.PIC1521DJT.sp,pressureController:PLANT.v.towerPressureController||'',controlRevision:'12FX-20261002'};
 if(typeof QHD!=='undefined'&&QHD)snap.refrigeration={units:QHD.units||null};
 return snap;
}
function ryanPlantStateText(){
 var s=ryanPlantStateEngine(),lines=[];lines.push(INFO.refrig_suction_12ga.d.slice(0,8).join('\n'));lines.push(cfOperatingPointContext12FZ());lines.push(cfC3OperatorContext12FY());
 lines.push('STATE ENGINE SNAPSHOT @ '+s.generatedAt);
 lines.push('Mode: '+s.mode+' | ESD: '+s.esd+' | Current board: '+s.screen);
 if(s.health&&!s.health.error){lines.push('Health: '+fmtRyanNum(s.health.score)+' ('+s.health.label+')');(s.health.concerns||[]).forEach(function(c){lines.push('Health concern ['+c[0]+']: '+c[1]);});}
 lines.push('Interlocks: '+s.interlocks.healthy+' healthy / '+s.interlocks.failed+' failed / '+s.interlocks.errors+' evaluation errors / '+s.interlocks.requiresVerification+' verification gaps ('+s.interlocks.total+' evaluated rows)');
 if(s.interlocks.failures.length){lines.push('FAILED / UNSATISFIED INTERLOCK CONDITIONS:');s.interlocks.failures.slice(0,35).forEach(function(x){lines.push('- '+x.interlock+' :: '+x.tag+' :: '+x.description);});}
 if(s.interlocks.evaluationErrors.length){lines.push('INTERLOCK EVALUATION ERRORS:');s.interlocks.evaluationErrors.slice(0,15).forEach(function(x){lines.push('- '+x.interlock+' :: '+x.tag+' :: '+x.reason);});}
 if(s.interlocks.verificationGaps.length){lines.push('KNOWN INTERLOCK VERIFICATION GAPS (do not invent values):');s.interlocks.verificationGaps.slice(0,25).forEach(function(x){lines.push('- '+x.interlock+' :: '+x.tag+' :: '+x.description);});}
 if(s.scenario&&s.scenario.active)lines.push('Active training scenario: '+s.scenario.active+' | elapsed '+fmtRyanNum(s.scenario.elapsed));
 if(s.expander)lines.push('Expander: '+(s.expander.running?'RUNNING':'STOPPED')+', IGV '+fmtRyanNum(s.expander.igv)+' | '+(s.expander.remote?'REMOTE':'LOCAL')+' | Board '+(s.expander.boardManual?'MANUAL':'AUTO')+' '+fmtRyanNum(s.expander.boardDemand)+'% | local '+fmtRyanNum(s.expander.localDemand)+'% | EX SP '+fmtRyanNum(s.expander.expanderSP)+' / JT SP '+fmtRyanNum(s.expander.jtSP)+' psig | active pressure loop '+s.expander.pressureController+(s.expander.trip?' | trip '+s.expander.trip:''));
 return lines.join('\n');
}

/* ===== Ryan Plant Graph =====
   A source-aware relationship graph for SME reasoning. "flow" edges below are
   limited to routes already documented in this simulator's Reference Library.
   Other associations are generated from the simulator's own equipment, loop,
   interlock, and board structures and are explicitly typed as associations --
   never silently promoted into P&ID-verified piping. */
var RYAN_PLANT_GRAPH_EDGES=[
 ['V-1040','V-1410','flow','Reference Library: flow_inletcomp'],
 ['V-1410','C-4100/C-4200','flow','Reference Library: flow_inletcomp'],
 ['C-4100/C-4200','AC-4101/AC-4201','flow','Reference Library/P&ID M1400'],
 ['AC-4101/AC-4201','V-1410','flow','Reference Library/P&ID M1400 corrected route'],
 ['V-1410','F-1412','flow','Reference Library: v1410'],
 ['F-1412','V-1413/V-1414/V-1415','flow','Reference Library: flow_inletcomp'],
 ['V-1413/V-1414/V-1415','F-1416/F-1417','flow','Reference Library: dehy entries'],
 ['F-1416/F-1417','E-1221/E-1222','flow','Reference Library: flow_chill'],
 ['E-1241','V-1421','flow','Reference Library/Quiz Flow Path'],
 ['V-1421 vapor','EX-1121','flow','Reference Library: flow_expdemeth'],
 ['EX-1121','T-1521','flow','Reference Library: flow_expdemeth'],
 ['V-1421 liquid (C2 RECOVERY)','T-1521','flow','P&ID 020185-AE-DW-M2135 Rev 10 / line 444-10in'],
 ['V-1421 liquid (C2 REJECTION)','E-1223/E-1224','flow','P&ID 020185-AE-DW-M2135 Rev 10 / line 434-12in'],
 ['V-1422','P-1619/P-1620','flow','Reference Library: flow_ngl'],
 ['P-1619/P-1620','P-1630/P-1635','flow','Reference Library: flow_ngl'],
 ['V-5010 vapor','C-5700','flow','Reference Library: flow_stab'],
 ['V-7500','P-7410/P-7420','flow','Reference Library: flow_hotoil'],
 ['P-7410/P-7420','H-7100','flow','Reference Library: flow_hotoil'],
 ['H-7100','E-1125','hot-oil duty','Reference Library: flow_hotoil'],
 ['H-7100','E-5000','hot-oil duty','Reference Library: flow_hotoil'],
 ['H-7100','E-5040','hot-oil duty','Reference Library: flow_hotoil']
];
function ryanPlantGraph(){
 var nodes={},edges=[];
 function node(id,type,meta){if(!id)return;nodes[id]=nodes[id]||{id:id,type:type||'unknown',meta:meta||{}};}
 function edge(a,b,rel,source,confidence){node(a);node(b);edges.push({from:a,to:b,relationship:rel,source:source,confidence:confidence||'SIMULATOR_DOCUMENTED'});}
 Object.keys(typeof EQP!=='undefined'?EQP:{}).forEach(function(k){var e=EQP[k]||{};node(e.tag||k,'equipment',{modelKey:k,equipmentType:e.t||null});});
 RYAN_PLANT_GRAPH_EDGES.forEach(function(e){edge(e[0],e[1],e[2],e[3],'SIMULATOR_REFERENCE_LIBRARY');});
 Object.keys(PLANT.L||{}).forEach(function(tag){node(tag,'control_loop',{boardState:true});});
 if(typeof INTERLOCK_DEFS!=='undefined')Object.keys(INTERLOCK_DEFS).forEach(function(k){var d=INTERLOCK_DEFS[k]||{},owner=d.title||k;node(owner,'controlled_object',{interlockKey:k});(d.items||[]).forEach(function(it){if(it.tag)edge(it.tag,owner,'interlock/permissive affects','Simulator INTERLOCK_DEFS','SIMULATOR_LOGIC');});});
 return {nodes:Object.keys(nodes).map(function(k){return nodes[k];}),edges:edges};
}
function ryanPlantGraphText(query){
 var g=ryanPlantGraph(),q=String(query||'').toLowerCase(),tokens=q.split(/[^a-z0-9-]+/).filter(function(t){return t.length>=3;});
 var selected=g.edges.filter(function(e){if(!tokens.length)return e.relationship==='flow'||e.relationship==='hot-oil duty';var hay=(e.from+' '+e.to+' '+e.relationship+' '+e.source).toLowerCase();return tokens.some(function(t){return hay.indexOf(t)>=0;});});
 if(tokens.length&&selected.length<8){g.edges.forEach(function(e){if(selected.indexOf(e)>=0)return;var hay=(e.from+' '+e.to+' '+e.relationship).toLowerCase();if(tokens.some(function(t){return hay.indexOf(t)>=0;}))selected.push(e);});}
 selected=selected.slice(0,60);
 var lines=['PLANT GRAPH: '+g.nodes.length+' nodes / '+g.edges.length+' relationships. Relationship type and source are explicit; association does not equal verified piping.'];
 selected.forEach(function(e){lines.push('- '+e.from+' --['+e.relationship+']--> '+e.to+' | '+e.confidence+' | '+e.source);});
 return lines.join('\n');
}
