var RYAN_DIGEST_JOB=null;
var RYAN_DIGEST_TIMER=null;
function ryanClearDigestJob(){
 try{localStorage.removeItem('ryanDigestJob');}catch(_e){}
 RYAN_DIGEST_JOB=null;
 if(RYAN_DIGEST_TIMER){clearTimeout(RYAN_DIGEST_TIMER);RYAN_DIGEST_TIMER=null;}
}
function ryanDigestExistingPidContext(){
 try{
  var rows=[];
  Object.keys(INFO||{}).filter(function(k){return k.indexOf('pid_m')===0;}).forEach(function(k){
   var rec=INFO[k]||{}; rows.push('['+(rec.t||k)+']\\n'+(rec.d||[]).join('\\n'));
  });
  return rows.join('\\n\\n').slice(0,16000);
 }catch(e){return '';}
}
function ryanStageBatchFacts(job,status,out){
 var ing=status&&status.ingestion;
 var items=ing&&Array.isArray(ing.facts)?ing.facts:[];
 if(!items.length){ryanClearDigestJob();var passDiag=(ing&&Array.isArray(ing.passes)&&ing.passes.length)?ing.passes.map(function(p){return (p.id||'pass')+': '+(p.facts||0)+' fact(s)'+(p.stopReason?' / '+p.stopReason:'');}).join(' | '):'No pass diagnostics returned.';out.innerHTML='<div style="background:#3a2b12;border:1px solid #7a5a24;border-radius:6px;padding:10px 12px;color:#ffd38a;font-size:12.5px;"><b>Ryan could not extract usable facts from this run.</b><br>This is an ingestion/extraction failure — it does <u>not</u> mean the P&amp;ID/manual contains no useful information.<br><span style="font-size:10.5px;color:#cdbb8d;">Pass diagnostics: '+ryanEscape(passDiag)+'</span>'+((ing&&ing.errors&&ing.errors.length)?'<br><span style="font-size:10.5px;color:#e3b985;">'+ryanEscape(ing.errors.join(' | '))+'</span>':'')+'<br>Confirm the attachment description says P&amp;ID/manual and retry. For a scanned P&amp;ID, export the drawing page as a high-resolution image or smaller PDF section and drop it into the same local box; HTTPS is not required.</div>';return;}
 var docHash=ryanHash('ai-batch|'+job.sourceLabel+'|'+job.batchId);
 var doc={id:'doc-'+docHash,title:'AI-read: '+job.sourceLabel,manufacturer:null,equipmentIds:[],knowledgeClass:'ai_digest',sourceType:'ai_digest',revisionDate:new Date().toISOString().slice(0,10),status:'active',importedAt:new Date().toISOString(),anthropicBatchId:job.batchId};
 var props=items.slice(0,RYAN_LEARN_FACT_CAP).map(function(it,i){
  return {id:'prop-'+docHash+'-'+i,sourceDocumentId:doc.id,sourcePage:it.page||null,equipmentIds:Array.isArray(it.equipmentIds)?it.equipmentIds:[],statement:String(it.statement||'').slice(0,1400),classification:it.classification||'other',verificationStatus:'DOCUMENT_EXTRACTED_UNVERIFIED',confidence:it.confidence||null,status:'staged',aiGenerated:true,approvedAt:null,createdAt:new Date().toISOString()};
 }).filter(function(p){return p.statement;});
 ryanStoreAll('documents',[doc],function(){ryanStoreAll('proposals',props,function(){ryanRefreshCache(function(){
  ryanClearDigestJob();
  var errs=(ing.errors||[]).length?'<div style="color:#ffcf9f;margin-top:5px;">Warnings: '+ing.errors.join(' | ')+'</div>':'';
  out.innerHTML=ryanLearnedFactReportHtml(props,job,(ing&&ing.passes?ing.passes.map(function(p){return (p.id||'pass')+': '+(p.facts||0)+' fact(s)';}).join(' | '):''),(ing&&ing.errors?ing.errors.length:0))+errs;
 });});});
}
function ryanBackendError(res){
 try{
  var d=res&&res.d;
  if(!d)return 'HTTP '+((res&&res.status)||'?')+' with no JSON response';
  if(typeof d.error==='string')return d.error;
  if(d.error&&typeof d.error.message==='string')return d.error.message;
  if(typeof d.message==='string')return d.message;
  var detail=JSON.stringify(d);
  return 'HTTP '+((res&&res.status)||'?')+(detail&&detail!=='{}'?': '+detail.slice(0,700):'');
 }catch(e){return 'HTTP '+((res&&res.status)||'?')+' (unreadable backend error)';}
}
