document.getElementById('libSearch').addEventListener('input',function(e){var v=e.target.value.trim();if(v&&libSel.cat!==null&&!cfDeviceListIsActive()){libSel.cat=null;libRenderCats();}clearTimeout(LIB_SEARCH_TIMER);LIB_SEARCH_TIMER=setTimeout(function(){if(document.getElementById('library').style.display==='block'&&document.getElementById('libSearch').value.trim()===v){LIB_LIST_FILTER=null;try{libRenderList(v||null);if(cfDeviceListIsActive()){libSel.key=null;libRenderDetail();}}catch(err){libShowFailure(err);}}},140);});
document.getElementById('libSearch').addEventListener('keydown',function(e){if(e.key==='Enter'){if(cfDeviceListIsActive()){e.preventDefault();clearTimeout(LIB_SEARCH_TIMER);var matches=cfDeviceListFiltered(cfDeviceListKind(),e.target.value.trim());cfDeviceListPaintList(e.target.value.trim());var precise=matches.filter(function(r){return r.confirmedTag&&cf3dDeviceNorm(r.confirmedTag)===cf3dDeviceNorm(e.target.value);});libSel.key=precise.length===1?precise[0].key:(matches.length===1?matches[0].key:null);libRenderDetail();return;}var q=e.target.value.trim(),k=libExactLearnedKey(q);if(k){e.preventDefault();libNavigateToLearned(k);}}});

/* ═══════ QUICK JUMP: large-tile, touch/stylus-friendly navigation panel.
   Same underlying category data as the library, but every tile is a big tappable
   button that immediately flies the camera there and closes the panel -- built for
   quick navigation on a big touchscreen rather than reading reference notes. ═══════ */
function renderJumpPanel(){
 var body=document.getElementById('jumpBody'); if(!body)return;
 var html='';
 LIB_CATS.forEach(function(cat){
  var equipOnly=cat[1].filter(function(k){return typeof EQP!=='undefined' && EQP[k];});
  if(!equipOnly.length)return;
  html+='<div style="margin-bottom:22px;">';
  html+='<div style="color:#8fb0d0;font-size:14px;font-weight:700;margin-bottom:10px;letter-spacing:0.3px;">'+cat[0]+'</div>';
  html+='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;">';
  equipOnly.forEach(function(k){
   var tag=(EQP[k]&&EQP[k].tag)||k;
   html+='<button class="jumptile" data-k="'+k+'" style="min-height:64px;padding:12px 10px;background:#182028;border:1.5px solid #2c3844;border-radius:10px;color:#dce6ee;font-size:14px;font-weight:600;cursor:pointer;touch-action:manipulation;text-align:center;line-height:1.3;">'+tag+'</button>';
  });
  html+='</div></div>';
 });
 body.innerHTML=html;
 body.querySelectorAll('.jumptile').forEach(function(btn){
  btn.addEventListener('click',function(){
   var k=btn.getAttribute('data-k');
   closeJumpPanel();
   go(k);
  });
  btn.addEventListener('touchstart',function(){btn.style.background='#24405c';btn.style.borderColor='#4a9eff';},{passive:true});
 });
}
function openJumpPanel(){document.getElementById('jumppanel').style.display='block'; renderJumpPanel();}
function closeJumpPanel(){document.getElementById('jumppanel').style.display='none';}
document.getElementById('jumpbtn').addEventListener('click',openJumpPanel);
document.getElementById('jumpClose').addEventListener('click',closeJumpPanel);
document.getElementById('jumppanel').addEventListener('click',function(e){if(e.target===this)closeJumpPanel();});

