function openQuizPanel(){ document.getElementById('quizpanel').style.display='block'; if(quizCurrent.length===0) buildQuiz(); renderQuiz(); }
function closeQuizPanel(){ document.getElementById('quizpanel').style.display='none'; }
document.getElementById('quizbtn').addEventListener('click',openQuizPanel);
document.getElementById('quizClose').addEventListener('click',closeQuizPanel);
document.getElementById('quizpanel').addEventListener('click',function(e){if(e.target===this)closeQuizPanel();});

var TREND_VIEW={key:null,endMs:null,spanMs:10*60*1000};
function trendEngineeringFloor(unit,cur){
 unit=String(unit||'').toUpperCase();
 if(unit.indexOf('PSI')>=0)return 10;
 if(unit.indexOf('DEG')>=0||unit.indexOf('°F')>=0)return 10;
 if(unit.indexOf('GPM')>=0)return 10;
 if(unit.indexOf('MMSCFD')>=0)return 8;
 if(unit.indexOf('SCF')>=0)return Math.max(100,Math.abs(cur)*0.05);
 if(unit.indexOf('%')>=0)return 8;
 return Math.max(4,Math.abs(cur)*0.03);
}


var RYAN_TREND_INSTALL_INFLIGHT={};
function ryanTrendSeriesBetween(key,startMs,endMs){var a=(TREND_LOG[key]||[]),t=(TREND_TIME[key]||[]),v=[],ts=[];for(var i=0;i<a.length;i++){var ti=t[i]||0;if(ti>=startMs&&ti<=endMs&&isFinite(a[i])){v.push(Number(a[i]));ts.push(ti);}}return {values:v,times:ts};}
function ryanTrendStatsBetween(key,startMs,endMs){var s=ryanTrendSeriesBetween(key,startMs,endMs),a=s.values;if(a.length<2)return null;var sum=0,lo=Infinity,hi=-Infinity;for(var i=0;i<a.length;i++){sum+=a[i];lo=Math.min(lo,a[i]);hi=Math.max(hi,a[i]);}var hours=Math.max((s.times[s.times.length-1]-s.times[0])/3600000,1/60),avg=sum/a.length;return {key:key,n:a.length,first:a[0],last:a[a.length-1],lo:lo,hi:hi,avg:avg,delta:a[a.length-1]-a[0],rateHr:(a[a.length-1]-a[0])/hours,start:s.times[0],end:s.times[s.times.length-1]};}
function ryanTrendCorrelation(k1,k2,startMs,endMs){var a=ryanTrendSeriesBetween(k1,startMs,endMs),b=ryanTrendSeriesBetween(k2,startMs,endMs),i=0,j=0,x=[],y=[];while(i<a.times.length&&j<b.times.length){var d=a.times[i]-b.times[j];if(Math.abs(d)<=90000){x.push(a.values[i]);y.push(b.values[j]);i++;j++;}else if(d<0)i++;else j++;}if(x.length<6)return null;var sx=0,sy=0;for(i=0;i<x.length;i++){sx+=x[i];sy+=y[i];}var mx=sx/x.length,my=sy/y.length,num=0,dx=0,dy=0;for(i=0;i<x.length;i++){var vx=x[i]-mx,vy=y[i]-my;num+=vx*vy;dx+=vx*vx;dy+=vy*vy;}if(!dx||!dy)return null;return {r:num/Math.sqrt(dx*dy),n:x.length};}
