function ryanTrendTags(text){var out=[],seen={},re=/\b([A-Z]{1,6})[-_ ]?(\d{3,5}[A-Z]?)\b/ig,m;while((m=re.exec(String(text||'')))){var tag=(m[1]+'-'+m[2]).toUpperCase();if(!seen[tag]){seen[tag]=1;out.push(tag);}}return out.slice(0,40);}
