 var stab=new THREE.Mesh(cfCylinderGeometry12JG(0.006,0.006,0.16,8),stabM); stab.rotation.x=Math.PI/2; stab.position.set(0.01,-0.01,-0.09); bowGroup.add(stab);
 var stabWeight=new THREE.Mesh(cfCylinderGeometry12JG(0.012,0.012,0.03,10),stabM); stabWeight.rotation.x=Math.PI/2; stabWeight.position.set(0.01,-0.01,-0.175); bowGroup.add(stabWeight);
