/* --- hunting state --- */
var bowEquipped=false, drawPower=0, drawHeld=false, drawFullT=0;
var arrowFlying=false, arrowT=0, arrowDur=1, arrowStart=new THREE.Vector3(), arrowEnd=new THREE.Vector3(), arrowTargetDeer=null, arrowWillHit=false;
