 var _expTin=(typeof PLANT!=='undefined'&&PLANT.v&&PLANT.v.expanderFeedTemp!=null)?PLANT.v.expanderFeedTemp:((typeof PLANT!=='undefined'&&PLANT.v&&PLANT.v.te1421a!=null)?PLANT.v.te1421a:-7.0);
