 var compSuc=clmp(_demP-23.6,180,340), compDis=Math.min(675,compSuc+r*144), pdi=466*Math.pow(Math.max(acfm,1)/7889,2), hp=(rpm<=0?0:Math.min(3700,2250*Math.pow(Math.max(_shaftLoad,0.01)/0.92,1.15)));
 var expBrgT=60+r*92, compBrgT=60+r*73, overspeedKick=Math.max(0,rpm-28400)*0.0025;
 var expVibX=r*0.019/0.99+overspeedKick+_wet*0.030, expVibY=r*0.071/0.99+overspeedKick*0.9+_wet*0.040, compVibX=r*0.138/0.99+overspeedKick*0.8, compVibY=r*0.094/0.99+overspeedKick*0.8;
 var thrust=run?clmp(118+121*r+Math.max(0,flowNow-152)*0.85+Math.max(0,(expIn-pi101)-626)*0.10,0,340):0; /* 12CH: live thrust load. Calibrated to ~239 psid at the observed 24,030 RPM / full-IGV point; rises with shaft load, flow and expansion differential so the OEM 300-psid trip is physically reachable instead of impossible. */
