/* Keeps the Schedule popup's Bulk-Edit and Notes form fields in PLANT state on every
   keystroke/selection, not just at Apply/Add-click time -- the fix for the tick-wipe
   bug (see schedulePopup()'s bulk-edit block comment for the full story). This listener
   deliberately does NOT call renderScreen() itself -- doing so on every keystroke would
   just reintroduce the focus-loss problem on every character typed; the 1-second
   PLANT.tick() cycle already re-renders regularly enough to reflect anything typed. */
document.getElementById('eqtscr').addEventListener('input',function(e){
 var t=e.target,id=t.id;
 if(id==='schedBulkEmp'||id==='schedBulkStart'||id==='schedBulkEnd'||id==='schedBulkCode'){
  if(!PLANT.schedBulkDraft)PLANT.schedBulkDraft={};
  var key=(id==='schedBulkEmp')?'emp':(id==='schedBulkStart')?'start':(id==='schedBulkEnd')?'end':'code';
  PLANT.schedBulkDraft[key]=t.value;
 } else if(id==='schedNoteDate'||id==='schedNoteInput'){
  if(!PLANT.schedNoteDraft)PLANT.schedNoteDraft={};
  PLANT.schedNoteDraft[id==='schedNoteDate'?'date':'text']=t.value;
 } else if(id==='schedCellNote'){
  if(!PLANT.schedCellNoteDraft)PLANT.schedCellNoteDraft={};
  PLANT.schedCellNoteDraft.text=t.value;
 } else if(id==='wpNumber'||id==='wpDesc'||id==='wpClosedBy'||id==='wpDate'){
  if(!PLANT.wpDraft)PLANT.wpDraft={};
  var wpKey=(id==='wpNumber')?'number':(id==='wpDesc')?'desc':(id==='wpClosedBy')?'closedBy':'date';
  PLANT.wpDraft[wpKey]=t.value;
 }
});
