  if(!PLANT.schedBulkDraft){var _firstActive=S.employees.filter(function(e){return e.active;})[0];PLANT.schedBulkDraft={emp:_firstActive?_firstActive.id:'',start:todayStr,end:todayStr,code:'D'};}
  var bd=PLANT.schedBulkDraft;
  s+='<div class="poc" style="margin:0 auto 10px;max-width:640px;">';
