  S.employees.forEach(function(e){if(e.active)s+='<option value="'+e.id+'"'+(e.id===bd.emp?' selected':'')+'>'+e.name+'</option>';});
  s+='</select>';
  s+='<input id="schedBulkStart" type="date" value="'+bd.start+'" style="background:#0b0f14;border:1px solid #2a333c;color:#cfe0f0;padding:3px 6px;border-radius:3px;font-size:11px;">';
  s+='<span style="color:#5a6b7c;">to</span>';
  s+='<input id="schedBulkEnd" type="date" value="'+bd.end+'" style="background:#0b0f14;border:1px solid #2a333c;color:#cfe0f0;padding:3px 6px;border-radius:3px;font-size:11px;">';
  s+='<select id="schedBulkCode" style="background:#0b0f14;border:1px solid #2a333c;color:#cfe0f0;padding:4px 6px;border-radius:3px;font-size:11px;">'
