 var s='<div class="pop"><div class="poph">SHIFT DASHBOARD<button data-act="popclose">Exit</button></div><div class="popb" style="display:block;">';
 s+='<div style="text-align:center;padding:8px 0;"><div style="font-size:12px;color:#cfe0f0;">'+new Date().toLocaleString()+' &middot; Operating Mode: <b>'+mode+'</b></div>';
 s+='<div style="font-size:20px;font-weight:700;color:'+h.color+';margin-top:4px;">Plant Health: '+h.score.toFixed(0)+' \u2014 '+h.label+'</div>';
