  var isValve=/^(?:PV|PCV|PDCV|FCV|FV|LCV|LV|TCV|TV|XV|SDV|ESD|ABV|ACV)[\s-]*\d+[A-Z0-9-]*$/i.test(tag);
  if(kind==='psv'?!isPsv:!isValve)return;
  var row=exact(tag);
