  facts.slice(0,60).forEach(function(f){cfDeviceListElement('p',String(f.statement||'')+' [Source: '+(f.sourceTitle||f.sourceDocumentId||'Pending')+(f.page?', page '+f.page:'')+'; '+(f.verificationStatus||'DOCUMENT_EXTRACTED_UNVERIFIED')+']',details);});
