/* ===== Material/lighting quality pass, adapted from the handoff's material-tuning
   logic (auditMaterials/tweakMaterial) -- ported for real this time using this file's
   own actual `scene` variable directly, rather than the handoff's window.scene-searching
   helpers (findScene/findRenderer), which is what made it look unportable at first look.
   Subtle: slightly boosts metalness/roughness realism on pipe/steel/vessel surfaces,
   very slightly increases roughness elsewhere, and enables shadow casting/receiving on
   smaller meshes. Purely cosmetic -- does not touch geometry, positions, physics, or any
   process/DCS logic, matching the same "visual-only" boundary the original feature drew. */
var CLEARFORK_WEATHERING=true;
function isPhysicalMesh(o){return o&&o.isMesh&&o.material&&!(o.userData&&(o.userData.isHUD||o.userData.screen||o.userData.overlay));}
function tweakMaterial(m,name){
 if(!m||!m.isMeshStandardMaterial)return;
 var n=(name||'').toLowerCase();
 if(CLEARFORK_WEATHERING){
  if(/pipe|steel|rail|ladder|structure|valve|vessel|tank|compressor|cooler/.test(n)){
   m.roughness=Math.max(.38,Math.min(.88,(m.roughness==null?.62:m.roughness)+.08));
   m.metalness=Math.max(.45,Math.min(.88,(m.metalness==null?.55:m.metalness)+.08));
  } else {
   m.roughness=Math.max(.48,Math.min(1,(m.roughness==null?.7:m.roughness)+.035));
  }
 }
 m.needsUpdate=true;
}
function auditMaterials(sc){
 var count=0;
 sc.traverse(function(o){
  if(!isPhysicalMesh(o))return;
  var mats=Array.isArray(o.material)?o.material:[o.material];
  mats.forEach(function(m){if(m&&m.isMeshStandardMaterial){tweakMaterial(m,o.name);count++;}});
  if(o.geometry&&o.geometry.attributes&&o.geometry.attributes.position&&o.geometry.attributes.position.count<65000){o.castShadow=true;o.receiveShadow=true;}
 });
 window.CLEARFORK_VISUAL_MATERIAL_AUDIT={standardMaterialsAdjusted:count,weathering:CLEARFORK_WEATHERING,checkedAt:new Date().toISOString()};
 return count;
}
auditMaterials(scene);
document.getElementById('cfWeatherToggle').addEventListener('click',function(){
 CLEARFORK_WEATHERING=!CLEARFORK_WEATHERING;
 this.textContent=(CLEARFORK_WEATHERING?'Weathering: ON':'Weathering: OFF');
 auditMaterials(scene);
});
