 dehySeq:{title:'Dehy Sequence',note:'This is the comprehensive shutdown list that gates the whole regeneration sequence (heat/cool bed switching), not a single valve -- matches the real "Dehy Sequence" DCS popup rather than being folded into XV-1410\'s narrower list.',items:[
  {tag:'Plant_ESD',desc:'Main Plant ESD',ok:function(){return !PLANT.esd;}},
  {tag:'PT-1410B',desc:'F-1412 Inlet Gas Pressure High-High Shutdown (setpoint Requires Verification)',ok:function(V){return (V.p1410-1.9)<1100;}},
  {tag:'LSHH-1410',desc:'V-1410 Inlet Gas Separator Liquid Level High-High',ok:function(V){return V.lvl1410<85;}},
  {tag:'PDT-1412',desc:'F-1412 Inlet Filter/Coalescer Differential Pressure High-High Shutdown — operator-confirmed: CHANGE at 15 PSID, facility ESD at 20 PSID',ok:function(V){return V.pdt1412<20;}},
  {tag:'LSHH-1412A',desc:'F-1412 Inlet Gas Filter Upper Liquid Level High-High (75%)',ok:function(V){return V.lvl1412a<75;}},
  {tag:'LSHH-1412B',desc:'F-1412 Inlet Gas Filter Lower Liquid Level High-High (75%)',ok:function(V){return V.lvl1412b<75;}},
  {tag:'PDT-1416A',desc:'Dehy Dust Filter (F-1416/F-1417) Differential Pressure High-High Shutdown -- confirmed real setpoints: 20 PSID trips, 15 PSID means the standby filter needs swapping in before it gets that far',ok:function(V){return (V.pdt1416a==null)||V.pdt1416a<20;}},
  {tag:'ME-1416',desc:'Process Gas Dew Point Temperature High-High Shutdown -- confirmed real setpoints: -100\u00b0F alarm, -10\u00b0F shutdown',ok:function(V){return (V.me1416==null)||V.me1416<-10;}},
  {tag:'TE-1417',desc:'Dehy Bed Process Gas Outlet Temperature High-High (setpoint Requires Verification)',ok:function(){return true;}},
  {tag:'TE-1311B',desc:'A-1311 Regen Gas Cooler Outlet Temperature High-High Shutdown -- confirmed real, 7/23/2026: 150\u00b0F HIHI shutdown',ok:function(V){return (V.te1311b==null)||V.te1311b<150;}},
  {tag:'LSHH-1418',desc:'V-1418 Regen Gas Scrubber Liquid Level High-High Shutdown (setpoint Requires Verification -- LT-1418 is live: current operator snapshot ~6%, LO alarm 20%, HI alarm 35%; LIC-1418 SP 18% auto-dumps through LCV-1418/XV-1418 toward 0% when in AUTO, but no separate HIHI switch setpoint has been confirmed)',ok:function(V){return (V.lt1418==null)||V.lt1418<35;}},
  {tag:'PSLL-1111',desc:'C-1111 Regen Gas Compressor Lube Oil Pressure Low-Low Shutdown (setpoint Requires Verification)',ok:function(){return true;}},
  {tag:'FT-1111A',desc:'C-1111 Regen Gas Compressor Outlet Flow Low-Low Shutdown -- confirmed real, 7/23/2026: LOLO 7.6 MMSCFD, LO 16 MMSCFD, HI 24 MMSCFD',ok:function(V){return (V.ft1111a==null)||V.ft1111a>7.6;}},
  {tag:'FT-1111B',desc:'C-1111 Regen Compressor Outlet Flow Low-Low Shutdown (source screenshot listed this alongside FT-1111A as a separate tag -- preserved as-is, not merged, since the source treats them as distinct; whether A and B are redundant/voted/separate measurements is still Pending P&ID confirmation)',ok:function(){return true;}},
  {tag:'TE-1111',desc:'C-1111 Lube Oil Temperature High-High Shutdown -- confirmed real, 7/23/2026: 190\u00b0F HIHI shutdown, 80\u00b0F LO alarm, 180\u00b0F HI alarm',ok:function(V){return (V.te1111==null)||V.te1111<190;}},
  {tag:'FT-1711',desc:'Regen Gas Heater (H-1711) Outlet Flow Low-Low Shutdown -- confirmed real, 7/23/2026: LOLO 7.2 MMSCFD, LO 12.2 MMSCFD, HI 24 MMSCFD',ok:function(V){return (V.ft1711==null)||V.ft1711>7.2;}},
  {tag:'TSHH-1711',desc:'Regen Gas Heater Stack Temperature High-High Shutdown (setpoint Requires Verification -- heater stack-temp physics not modeled yet, separate from the confirmed TE-1711 outlet-temp alarms of 450/535\u00b0F)',ok:function(){return true;}},
  {tag:'PIT-9241A',desc:'Instrument Air Header Pressure Low-Low Shutdown — PIT-9241A verified LOLO 75 psig facility ESD; LO 90 psig; HI 160 psig; normal ~126.6 psig',ok:function(){return true;}},
  {tag:'TE-1416',desc:'Dehy Dust Filter Inlet Temperature High-High Shutdown -- confirmed real setpoint: 150\u00b0F',ok:function(V){return (V.te1416==null)||V.te1416<150;}},
 ]},
