 pv6805a:{title:'PIC-6805A / PV-6805A (regen dry-out branch to inlet compressors)',note:'Confirmed real from a direct photo of the real DCS popup -- short 6-row list. This branch is normally closed (manual, 0% open) -- Ryan has never observed it open in service.',items:[
  {tag:'Plant_ESD',desc:'Main Plant ESD',ok:function(){return !PLANT.esd;}},
  {tag:'PIT-9241A',desc:'Instrument Air Header Pressure Low-Low Shutdown — PIT-9241A verified LOLO 75 psig facility ESD; LO 90 psig; HI 160 psig; normal ~126.6 psig',ok:function(){return true;}},
  {tag:'PIT-6805A',desc:'Regen Gas to Inlet-Compressor Pressure High-High Shutdown -- confirmed real: 525 psig HI alarm, 550 psig HIHI shutdown',ok:function(V,L){return (L.PIC6805A==null)||L.PIC6805A.pv<550;}},
  {tag:'PIT-4250C',desc:'Inlet Compressor Recycle Gas Pressure High-High Shutdown (setpoint Requires Verification)',ok:function(V,L){return Math.max(L.PIC4250A.pv,L.PIC4250B.pv)<1200;}},
  {tag:'LSHH-1418',desc:'V-1418 Regen Gas Scrubber Liquid Level High-High (setpoint Requires Verification)',ok:function(V){return (V.lt1418==null)||V.lt1418<35;}},
  {tag:'INLET_COMP_RUN',desc:'No Inlet Compressor Running (permissive) -- this branch should not open unless an inlet compressor is running and all permissives are healthy',ok:function(){return (PLANT.cmp.c41?!PLANT.cmp.c41.run:true)&&(PLANT.cmp.c42?!PLANT.cmp.c42.run:true);}},
 ]},
