   if(it.possibleCauses)row+='<div style="margin-bottom:4px;"><b style="color:#e0c070;">Possible Causes:</b><ul style="margin:3px 0 0 16px;padding:0;">'+it.possibleCauses.map(function(c){return '<li>'+c+'</li>';}).join('')+'</ul></div>';
   if(it.operatorActions)row+='<div style="margin-bottom:4px;"><b style="color:#8aff9f;">Operator Actions:</b><ol style="margin:3px 0 0 16px;padding:0;">'+it.operatorActions.map(function(c){return '<li>'+c+'</li>';}).join('')+'</ol></div>';
   if(it.protects)row+='<div style="margin-bottom:2px;"><b style="color:#cfe6ff;">Protects:</b> '+it.protects.join(', ')+'</div>';
   if(it.affectedBy)row+='<div style="margin-bottom:4px;"><b style="color:#cfe6ff;">Affected By:</b> '+it.affectedBy.join(', ')+'</div>';
   if(it.note)row+='<div style="margin-top:4px;padding-top:4px;border-top:1px solid #22303c;color:#c9b98a;font-style:italic;">'+it.note+'</div>';
