 s+='<text x="935" y="82" fill="#26303a" font-size="6.8">PCV-1623: LIC-1422B / PIC-1623</text><text x="935" y="230" fill="#26303a" font-size="6.8">PCV-1624: LIC-1422C / PIC-1624</text>';
 s+=tg(235,370,'PIC-1623',L.PIC1623.pv.toFixed(0),'PSIG')+tg(350,370,'PIC-1624',L.PIC1624.pv.toFixed(0),'PSIG')+tg(465,370,'LT-1422',L.LIC1422.pv.toFixed(1),'%')+tg(580,370,'C2 in NGL',(V.c2ngl||1).toFixed(2),'mol%')+tg(695,370,'Booster VFD',(V.nglPumpSpd||70).toFixed(0),'% spd');
 s+='<rect x="800" y="350" width="132" height="50" fill="#f2e31b" stroke="#1b1f24"/>'
