/* Startup self-check: verify every screen this file's own nav/tab list expects
   actually has a real SCR.xxx renderer function registered. Catches exactly the
   "last-definition-wins" class of bug this project has hit before (a later
   duplicate SCR.xxx=function() silently overwriting/shadowing an earlier one,
   or a screen key referenced in a nav list with no matching renderer at all)
   at load time, via a clear console error, instead of only being discovered
   when someone happens to click that specific tab. Diagnostic only -- does not
   change any behavior, and only ever writes to the console/window, nothing UI-visible. */
(function(){
 var expected=['plinlet','inlcomp','rescomp','pmps','coldsep','demeth','reb','stab','refsys','refcond','gasgas','inlsys','dehy','regen','util','outlet','rsv','prodpump','stabinlet','hotoil','inlsep','expander','fuelgas','pdc','refcomp'];
 var missing=[];
 if(typeof SCR!=='object'){ missing=expected.slice(); }
 else expected.forEach(function(k){ if(typeof SCR[k]!=='function') missing.push(k); });
 if(missing.length) console.error('[Clearfork Health] Missing screen renderers:',missing);
 else console.info('[Clearfork Health] Canonical control-board registry ready:',expected.length,'screens');
 window.CLEARFORK_HEALTH={checkedAt:new Date().toISOString(),screenCount:(typeof SCR==='object')?Object.keys(SCR).length:0,missingScreens:missing,status:missing.length?'ATTENTION':'READY'};
})();

/* ===== Multi-window live sync ("Open on 2nd Screen") =====
   Placed at the very end of the file on purpose -- everything it wraps (PLANT.tick,
   qhdTick, expTick, renderScreen, qhdRender, expRender, ctRender, renderNav) must
   already be its REAL, final definition (this file has several places where an
   earlier duplicate is silently dead code; putting this block last guarantees it
   only ever touches the live one).

   Design: exactly one window is ever authoritative. The window you open normally
   (double-click the file, or paste the URL) is always the HOST and runs physics
   exactly as this file always has. Clicking "Open on 2nd Screen" spawns a CLIENT
   window (via window.open, so it has window.opener) that never runs its own
   physics -- it only (a) mirrors real clicks to/from the host so a shared popup
   feels interactive in both windows, and (b) receives a full state snapshot from
   the host once a second so its OWN screens/3D view stay correct even when it's
   looking at something the host isn't. Nothing about how any click already
   mutates PLANT/QHD/EXP/CTRL was changed -- this only adds a sync layer on top. */
function cfSafeClone(o){try{return JSON.parse(JSON.stringify(o));}catch(e){return null;}}
function cfDeepMerge(dst,src){
 if(!src||typeof src!=='object')return;
 Object.keys(src).forEach(function(k){
  var sv=src[k];
  if(sv&&typeof sv==='object'&&!Array.isArray(sv)){
   if(!dst[k]||typeof dst[k]!=='object')dst[k]={};
   cfDeepMerge(dst[k],sv);
  } else dst[k]=sv;
 });
}
function cfSnapshot(){
 return {PLANT:cfSafeClone(PLANT),QHD:cfSafeClone(QHD),EXP:cfSafeClone(EXP),SCEN:cfSafeClone(SCEN)};
}
function cfApplySnapshot(state){
 if(!state)return;
 if(state.PLANT)cfDeepMerge(PLANT,state.PLANT);
 if(state.QHD)cfDeepMerge(QHD,state.QHD);
 if(state.EXP)cfDeepMerge(EXP,state.EXP);
 if(state.SCEN)cfDeepMerge(SCEN,state.SCEN);
 try{
  if(document.getElementById('eqt').style.display!=='none')renderScreen();
  if(document.getElementById('qhd').style.display!=='none')qhdRender();
  if(document.getElementById('acmtc').style.display!=='none')expRender();
  if(document.getElementById('ctrl').style.display!=='none')ctRender();
  renderNav();
 }catch(err){console.error('[Clearfork Sync] render after snapshot failed',err);}
}
function cfBuildSelector(el){
 if(el.id)return '#'+el.id;
 if(el.classList){
  if(el.classList.contains('ack'))return '#eqt .ack';
  if(el.classList.contains('rst'))return '#eqt .rst';
  if(el.classList.contains('esd'))return '#eqt .esd';
 }
 var attrs=['data-act','data-v','data-l','data-c','data-key','data-e','data-d','data-s','data-sp','data-md','data-o'];
 var parts=[];
 attrs.forEach(function(a){var v=el.getAttribute&&el.getAttribute(a);if(v!=null)parts.push('['+a+'="'+String(v).replace(/"/g,'\\"')+'"]');});
 if(!parts.length)return null;
 return el.tagName.toLowerCase()+parts.join('');
}
function cfPanelFor(el){var host=el.closest('#eqt, #qhd, #ctrl, #acmtc');return host?host.id:null;}
var CF_MIRROR_EXCLUDE_ACT={trend:1,ilk:1,cvinfo:1}; /* 'popclose' deliberately REMOVED this session -- it was excluded from cross-window click-mirroring while every *opening* action (planthealth, shiftdash, etc.) WAS mirrored. That asymmetry meant: close a popup on one window, but the other window's state still thinks it's open -- and the next periodic full-state snapshot push (see cfSnapshot/cfApplySnapshot below) would then shove that stale "still open" popup state back onto the window where it was just closed, making it look like the popup "keeps popping back up". Mirroring the close the same way opens are mirrored keeps both windows' popup state consistent so a snapshot can't resurrect it. */
function cfMirrorHandler(e){
 if(CF.suppress)return;
 var el=e.target.closest('[data-act],[data-sp],[data-md],button[id],.ack,.rst,.esd');
 if(!el)return;
 if(!el.closest('#eqtscr,#qhd,#ctrl,#acmtc,.ehead'))return;
 var act=el.getAttribute&&el.getAttribute('data-act');
 var loop=el.getAttribute('data-l')||el.getAttribute('data-sp')||el.getAttribute('data-md');
 if(/^(igv|igvmode|igvlocal|igvremote|igvman|igvauto|igvmatch|exprun|erun)$/.test(act||'')||/^(aAuto|aCascade|aStart|aDn|aUp)$/.test(el.id||'')||/^(PIC1521DEX|PIC1521DJT)$/.test(loop||''))return;
 if(act&&CF_MIRROR_EXCLUDE_ACT[act])return;
 var panel=cfPanelFor(el); if(!panel)return;
 var sel=cfBuildSelector(el); if(!sel)return;
 var peer=IS_CLIENT?window.opener:CF.child;
 if(!peer||peer.closed)return;
 try{peer.postMessage({kind:'cfClick',panel:panel,selector:sel},'*');}catch(err){}
}
document.addEventListener('click',cfMirrorHandler,true);
function cfReplayClick(data){
 try{
  var panelEl=document.getElementById(data.panel);
  if(!panelEl||panelEl.style.display==='none')return; /* peer isn't on the same popup -- the periodic snapshot still keeps its data correct */
  var target=document.querySelector(data.selector);
  if(!target)return;
  CF.suppress=true; target.click(); CF.suppress=false;
 }catch(err){CF.suppress=false;}
}
function cfBroadcastSnapshot(){
 if(IS_CLIENT||!CF.child||CF.child.closed)return;
 try{CF.child.postMessage({kind:'cfSnapshot',state:cfSnapshot()},'*');}catch(err){}
}
window.addEventListener('message',function(ev){
 if(!ev.data||typeof ev.data!=='object')return;
 if(ev.data.kind==='cfSnapshot'){
  if(IS_CLIENT&&ev.source===window.opener)cfApplySnapshot(ev.data.state);
 } else if(ev.data.kind==='cfClick'){
  var fromPeer=IS_CLIENT?(ev.source===window.opener):(ev.source===CF.child);
  if(fromPeer)cfReplayClick(ev.data);
 }
});
(function(){
 var btn=document.getElementById('cfOpenSecond');
 if(IS_CLIENT){
  if(btn)btn.style.display='none';
  var banner=document.createElement('div');
  banner.id='cfClientBanner';
  banner.style.cssText='position:fixed;top:8px;left:10px;z-index:55;background:#0d1116;border:1px solid #2a7a7a;border-radius:8px;padding:5px 10px;font-family:Consolas,monospace;font-size:11px;color:#9af0f0;box-shadow:0 2px 8px rgba(0,0,0,0.4);';
  banner.textContent='\uD83D\uDD17 2nd-screen view \u2014 synced to primary window';
  document.body.appendChild(banner);
  document.title='[2nd Screen] '+document.title;
  /* this window never computes physics -- it only mirrors clicks and renders
     whatever the host broadcasts, so it can never drift or fight with the host */
  PLANT.tick=function(){};
  PLANT.tickWeather=function(){};
  qhdTick=function(){qhdRender();};
  expTick=function(){expRender();};
  setInterval(function(){
   if((!window.opener||window.opener.closed)&&!document.getElementById('cfLostLink')){
    var w=document.createElement('div');
    w.id='cfLostLink';
    w.style.cssText='position:fixed;top:40px;left:10px;z-index:56;background:#3a1c1c;border:1px solid #9c3a3a;border-radius:8px;padding:6px 10px;font-family:Consolas,monospace;font-size:11px;color:#ffbfbf;max-width:260px;';
    w.textContent='Primary window closed \u2014 this view is frozen. Reopen the simulator normally (not via this window) to resume.';
    document.body.appendChild(w);
   }
  },2000);
 } else if(btn){
  btn.addEventListener('click',function(){
   if(CF.child&&!CF.child.closed){CF.child.focus();return;}
   var url=location.href.replace(/[?#].*$/,'')+'?cfClient=1';
   var w=window.open(url,'clearfork_secondary','width=1400,height=900');
   if(w)CF.child=w;
  });
  setInterval(cfBroadcastSnapshot,1000);
 }
})();

/* ===== Planned Outage / Maintenance Aging System =====
   Gated entirely behind PLANT.maintAging (default OFF) -- the Outages button only
   shows when it's on, and outageTick() itself is a no-op while it's off, so turning
   Aging off genuinely pauses everything rather than just hiding the UI.
   Only two entries below have a real, Ryan-confirmed interval AND duration: the
   compressor oil/filter PM (yearly, 2 hours, per-unit) and the dehy molecular-sieve
   replacement (every 10 years, 4-7 days, facility-wide). Every other entry is an
   explicitly-labeled placeholder example -- included so the panel demonstrates the
   full facility-scope/bundling behavior, not because its interval or duration is
   confirmed. Replace or remove them once real Clear Fork work-package data exists. */
var OUTAGE_PHASES=[['Shutdown / Isolation',0.10],['Depressure / Make Safe',0.10],['Maintenance Work',0.60],['Inspection / Close-Up',0.15],['Ready for Completion',0.05]];
var OUTAGE_DEFS=[
 {id:'c41_oil',name:'C-4100 Oil/Filter Change',scope:'c41',intervalText:'Yearly (confirmed real)',intervalReal:true,durationHours:2,durationReal:true},
 {id:'c42_oil',name:'C-4200 Oil/Filter Change',scope:'c42',intervalText:'Yearly (confirmed real)',intervalReal:true,durationHours:2,durationReal:true},
 {id:'c61_oil',name:'C-6100 Oil/Filter Change',scope:'c61',intervalText:'Yearly (confirmed real)',intervalReal:true,durationHours:2,durationReal:true},
 {id:'c62_oil',name:'C-6200 Oil/Filter Change',scope:'c62',intervalText:'Yearly (confirmed real)',intervalReal:true,durationHours:2,durationReal:true},
 {id:'c63_oil',name:'C-6300 Oil/Filter Change',scope:'c63',intervalText:'Yearly (confirmed real)',intervalReal:true,durationHours:2,durationReal:true},
 {id:'molsieve',name:'Dehy Molecular Sieve Replacement (V-1413/1414/1415)',scope:'facility',intervalText:'Every 10 years (confirmed real)',intervalReal:true,durationHours:132,durationReal:true,
  bundleNote:'Confirmed real operator guidance (Ryan): this multi-day facility outage is the natural time to bundle in other facility-scope work.'},
 {id:'residue_filter',name:'Residue Filter Element Change (F-6800)',scope:'facility',intervalText:'Requires Verification \u2014 example placeholder, not a confirmed Clear Fork interval',intervalReal:false,durationHours:8,durationReal:false},
 {id:'e1241_tube',name:'E-1241 Chiller Tube-Bundle Repair',scope:'facility',intervalText:'Requires Verification \u2014 example placeholder, not a confirmed Clear Fork interval',intervalReal:false,durationHours:24,durationReal:false},
 {id:'v1421_mi',name:'V-1421 Internal MI Inspection',scope:'facility',intervalText:'Requires Verification \u2014 example placeholder, not a confirmed Clear Fork interval',intervalReal:false,durationHours:16,durationReal:false},
 {id:'t1521_mi',name:'T-1521 Internal MI Inspection',scope:'facility',intervalText:'Requires Verification \u2014 example placeholder, not a confirmed Clear Fork interval',intervalReal:false,durationHours:16,durationReal:false},
 {id:'gas_slugnip_repair',name:'Inlet Slug Catcher Nipple Repair (unplanned gas release)',scope:'facility',intervalText:'Unplanned corrective repair, not a PM interval \u2014 triggered by a real gas-ESD training scenario',intervalReal:false,durationHours:8,durationReal:false,
  bundleNote:'Operator-described real event (Ryan): a small-bore nipple failed off the inlet slug catcher, releasing gas and tripping the plant on gas ESD. Ryan described the real repair as taking roughly 8 hours, with some variation depending on conditions \u2014 that approximate figure, not an exact confirmed duration, is what drives this outage timer.'},
];
function outageDef(id){return OUTAGE_DEFS.filter(function(d){return d.id===id;})[0];}
if(PLANT.maintAging==null)PLANT.maintAging=false;
if(PLANT.simLive==null)PLANT.simLive=true; /* master Play/Pause (added this session) -- see livePanel below. Live by default so the dashboard "just works" continuously; Pause freezes outage aging AND stops random System Lead calls, on top of/independent from the older Maintenance Aging toggle above. */
if(!PLANT.outageState)PLANT.outageState={};
if(!PLANT.outageHistory)PLANT.outageHistory=[];
if(!PLANT.outageSpeed)PLANT.outageSpeed=1;
function outagePhaseAt(def,elapsedHours){
 var frac=Math.min(1,elapsedHours/def.durationHours),acc=0;
 for(var i=0;i<OUTAGE_PHASES.length;i++){acc+=OUTAGE_PHASES[i][1];if(frac<=acc||i===OUTAGE_PHASES.length-1)return{idx:i,name:OUTAGE_PHASES[i][0],frac:frac};}
}
function outageStart(id){
 var def=outageDef(id);if(!def)return;
 PLANT.outageState[id]={status:'active',elapsedHours:0};
 if(def.scope==='facility'){PLANT.esd=true;alarm('OUTAGE STARTED: '+def.name+' \u2014 facility placed in safe shutdown for the duration. Restart afterward is a normal operator action, not automatic.');}
 else{var c=PLANT.cmp[def.scope];if(c){c.run=false;c.maintLock=true;}alarm('OUTAGE STARTED: '+def.name+' \u2014 '+(c?c.name:def.scope)+' isolated and locked out; remaining units cover the load if capacity allows.');}
 renderOutagePanel();renderScreen();
}
function outageSchedule(id,hoursFromNow){
 var def=outageDef(id);if(!def)return;
 PLANT.outageState[id]={status:'scheduled',scheduledInHours:hoursFromNow,elapsedSchedWaitHours:0};
 alarm('OUTAGE SCHEDULED: '+def.name+' in '+hoursFromNow.toFixed(1)+' sim-hours');
 renderOutagePanel();
}
function outageCancel(id){delete PLANT.outageState[id];renderOutagePanel();}
function outageForceComplete(id){var st=PLANT.outageState[id];if(!st||st.status!=='active')return;var def=outageDef(id);st.elapsedHours=def.durationHours;outageComplete(id);}
function outageComplete(id){
 var def=outageDef(id);if(!def)return;
 PLANT.outageHistory.unshift({id:id,name:def.name,completedAt:new Date().toISOString(),durationHours:def.durationHours});
 if(def.scope!=='facility'){var c=PLANT.cmp[def.scope];if(c)c.maintLock=false;}
 delete PLANT.outageState[id];
 alarm('OUTAGE COMPLETE: '+def.name+(def.scope==='facility'?' \u2014 facility restart still requires normal permissives/checks':' \u2014 lockout released, ready to restart'));
 renderOutagePanel();renderScreen();
}
function outageTick(){
 var nowMs=Date.now();
 if(PLANT._outageLastMs==null)PLANT._outageLastMs=nowMs;
 var dtSec=Math.max(0,Math.min(5,(nowMs-PLANT._outageLastMs)/1000));
 PLANT._outageLastMs=nowMs; /* always advance the clock, even while paused/disabled below -- otherwise paused real time gets "caught up" all at once the moment Play/Aging is switched back on, which would be a real bug, not a feature. */
 if(!PLANT.maintAging||!PLANT.simLive)return;
 var dtHours=dtSec*0.02*(PLANT.outageSpeed||1); /* ~50 real seconds per sim-hour at 1x */
 var panelOpen=document.getElementById('outagePanel').style.display!=='none';
 Object.keys(PLANT.outageState).forEach(function(id){
  var st=PLANT.outageState[id],def=outageDef(id);if(!def)return;
  if(st.status==='scheduled'){st.elapsedSchedWaitHours=(st.elapsedSchedWaitHours||0)+dtHours;if(st.elapsedSchedWaitHours>=st.scheduledInHours)outageStart(id);}
  else if(st.status==='active'){st.elapsedHours+=dtHours;if(st.elapsedHours>=def.durationHours)outageComplete(id);}
 });
 if(panelOpen)renderOutagePanel();
}
setInterval(outageTick,1000);
function renderOutagePanel(){
 var body=document.getElementById('outageBody');if(!body)return;
 var html='<div style="font-size:11px;color:#9aa6b2;margin-bottom:12px;">Only the compressor oil/filter PM and the dehy molecular-sieve replacement below have a confirmed real interval and duration (Ryan, direct operator knowledge). Everything else is an explicitly-marked placeholder example.</div>';
 OUTAGE_DEFS.forEach(function(def){
  var st=PLANT.outageState[def.id];
  html+='<div style="background:#141a22;border:1px solid #2a3542;border-radius:8px;padding:10px 14px;margin-bottom:8px;">'+
   '<div style="display:flex;justify-content:space-between;align-items:baseline;"><b style="color:#dce6ee;font-size:13px;">'+def.name+'</b><span style="font-size:10.5px;font-weight:700;color:'+(def.scope==='facility'?'#ff9a70':'#7fe0a0')+';">'+(def.scope==='facility'?'FACILITY SHUTDOWN':'EQUIPMENT ONLY ('+(PLANT.cmp[def.scope]?PLANT.cmp[def.scope].name:def.scope)+')')+'</span></div>'+
   '<div style="font-size:11px;color:'+(def.intervalReal?'#8aff9f':'#e0c070')+';margin-top:3px;">Interval: '+def.intervalText+' &middot; Duration: '+(def.durationReal?def.durationHours+' hrs (confirmed real)':'~'+def.durationHours+' hrs (placeholder)')+'</div>';
  if(def.bundleNote)html+='<div style="font-size:10.5px;color:#c9b98a;font-style:italic;margin-top:4px;">'+def.bundleNote+' Consider bundling other facility-scope work into this same window.</div>';
  if(!st){
   html+='<div style="margin-top:8px;"><button data-outact="start" data-id="'+def.id+'" style="background:#1f7a3a;color:#fff;border:none;border-radius:4px;padding:5px 12px;cursor:pointer;font-weight:700;font-size:11px;margin-right:6px;">Start Now</button>'+
    '<button data-outact="schedule" data-id="'+def.id+'" style="background:#243140;border:1px solid #3a4a5c;color:#cfe6ff;border-radius:4px;padding:5px 12px;cursor:pointer;font-weight:700;font-size:11px;">Schedule\u2026</button></div>';
  }else if(st.status==='scheduled'){
   var remain=Math.max(0,st.scheduledInHours-(st.elapsedSchedWaitHours||0));
   html+='<div style="margin-top:8px;color:#8fb0d0;font-size:11.5px;">Scheduled \u2014 starts in '+remain.toFixed(1)+' sim-hours. <button data-outact="cancel" data-id="'+def.id+'" style="margin-left:8px;background:#3a2020;border:1px solid #7a3a3a;color:#ffb0b0;border-radius:4px;padding:3px 10px;cursor:pointer;font-size:10.5px;">Cancel</button></div>';
  }else if(st.status==='active'){
   var ph=outagePhaseAt(def,st.elapsedHours),remainH=Math.max(0,def.durationHours-st.elapsedHours);
   html+='<div style="margin-top:8px;"><div style="background:#1a2028;border-radius:4px;height:8px;overflow:hidden;margin-bottom:5px;"><div style="background:#3fb4e6;height:100%;width:'+(ph.frac*100).toFixed(0)+'%;"></div></div>'+
    '<div style="font-size:11.5px;color:#7fe0ff;">Phase: <b>'+ph.name+'</b> &middot; '+remainH.toFixed(1)+' hrs remaining</div>'+
    '<button data-outact="forcecomplete" data-id="'+def.id+'" style="margin-top:6px;background:#243140;border:1px solid #3a4a5c;color:#cfe6ff;border-radius:4px;padding:4px 10px;cursor:pointer;font-size:10.5px;">Complete Now (training shortcut)</button></div>';
  }
  html+='</div>';
 });
 var hist=PLANT.outageHistory||[];
 html+='<div style="margin-top:16px;font-size:12px;font-weight:700;color:#9aa6b2;">Completed outages ('+hist.length+')</div>';
 html+=hist.length?hist.slice(0,20).map(function(h){return '<div style="font-size:11px;color:#8fa0b2;padding:3px 0;border-top:1px solid #22303c;">'+new Date(h.completedAt).toLocaleString()+' \u2014 '+h.name+' ('+h.durationHours+' hrs)</div>';}).join(''):'<div style="font-size:11px;color:#5a6b7c;font-style:italic;">None yet.</div>';
 body.innerHTML=html;
 body.querySelectorAll('[data-outact]').forEach(function(b){
  b.addEventListener('click',function(){
   var act=b.getAttribute('data-outact'),id=b.getAttribute('data-id');
   if(act==='start')outageStart(id);
   else if(act==='cancel')outageCancel(id);
   else if(act==='forcecomplete')outageForceComplete(id);
   else if(act==='schedule'){var h=prompt('Schedule how many sim-hours from now?','4');var hv=parseFloat(h);if(!isNaN(hv)&&hv>0)outageSchedule(id,hv);}
  });
 });
}
function openOutagePanel(){document.getElementById('outagePanel').style.display='block';renderOutagePanel();}
function closeOutagePanel(){document.getElementById('outagePanel').style.display='none';}
document.getElementById('outageClose').addEventListener('click',closeOutagePanel);
document.getElementById('outagePanel').addEventListener('click',function(e){if(e.target===this)closeOutagePanel();});
document.getElementById('outageSpeedSel').addEventListener('change',function(e){PLANT.outageSpeed=parseInt(e.target.value,10)||1;});
document.getElementById('cfOutagesBtn').addEventListener('click',openOutagePanel);
document.getElementById('cfMaintAgingToggle').addEventListener('click',function(){
 PLANT.maintAging=!PLANT.maintAging;
 this.textContent='Maintenance Aging: '+(PLANT.maintAging?'ON':'OFF');
 var btn=document.getElementById('cfOutagesBtn');
 if(PLANT.maintAging){btn.style.display='inline-block';}
 else{btn.style.display='none';closeOutagePanel();} /* outageTick() itself no-ops while maintAging is off, so this genuinely pauses progression, not just hides the UI */
});
/* ═══ Live / Pause master control + random System Lead calls + Command
   Center flash (added this session). Ryan's stated goal: this runs
   continuously on a screen like a real dashboard. Play = plant ages
   (subject to the Maintenance Aging toggle above still also being on) and
   System Lead may call at random, unannounced, same as a real shift.
   Pause freezes both -- intended for when you need to step away or explain
   something without the clock or a call landing on top of you. ═══ */
function leadRandomIntervalMs(){return (10+Math.random()*20)*60*1000;} /* 10-30 real minutes between calls -- sporadic, not constant pinging, for a dashboard meant to sit on a screen for hours */
if(window.CMD_LEAD_STATE.nextCallInMs==null)window.CMD_LEAD_STATE.nextCallInMs=leadRandomIntervalMs();
var CMD_FLASH_IV=null;
function flashCommandCenterStart(){
 var btn=document.getElementById('cmdcenterbtn'); if(!btn||CMD_FLASH_IV)return;
 var on=false;
 CMD_FLASH_IV=setInterval(function(){
  on=!on;
  btn.style.background=on?'#ff3b3b':'#1c3a5c';
  btn.style.color=on?'#fff':'#bfe0ff';
  btn.style.boxShadow=on?'0 0 14px 4px rgba(255,59,59,0.75)':'none';
 },500);
}
function flashCommandCenterStop(){
 if(CMD_FLASH_IV){clearInterval(CMD_FLASH_IV);CMD_FLASH_IV=null;}
 var btn=document.getElementById('cmdcenterbtn'); if(btn){btn.style.background='#1c3a5c';btn.style.color='#bfe0ff';btn.style.boxShadow='none';}
}
function leadAutoTick(){
 var nowMs=Date.now();
 if(PLANT._leadLastMs==null){PLANT._leadLastMs=nowMs;return;}
 var dtMs=nowMs-PLANT._leadLastMs;
 PLANT._leadLastMs=nowMs; /* same "always advance the clock" pattern as outageTick -- paused time must not bank up and fire a call the instant Play resumes */
 if(!PLANT.simLive||window.CMD_LEAD_STATE.active)return;
 window.CMD_LEAD_STATE.nextCallInMs-=dtMs;
 if(window.CMD_LEAD_STATE.nextCallInMs<=0){
  var ks=CMD_LEAD_SCENARIOS.map(function(s){return s.id;});
  var pick=ks[Math.floor(Math.random()*ks.length)];
  startLeadScenario(pick);
  window.CMD_LEAD_STATE.nextCallInMs=leadRandomIntervalMs();
  var ccOpen=document.getElementById('cmdcenter').style.display!=='none';
  if(ccOpen){CMD_TAB='lead';cmdRenderTab();}
  else{flashCommandCenterStart();}
  alarmToast('SYSTEM LEAD CALLING \u2014 open Command Center \u2192 System Lead');
 }
}
setInterval(leadAutoTick,5000);
function renderLivePanel(){
 var body=document.getElementById('liveBody'); if(!body)return;
 var live=PLANT.simLive;
 var nextMin=Math.max(0,(window.CMD_LEAD_STATE.nextCallInMs||0)/60000);
 body.innerHTML=
  '<div style="text-align:center;margin-bottom:16px;">'+
   '<div style="font-size:15px;font-weight:700;color:'+(live?'#7fe08a':'#ff9f70')+';">'+(live?'\ud83d\udfe2 LIVE':'\u23f8\ufe0f PAUSED')+'</div>'+
   '<div style="font-size:11.5px;color:#8a97a4;margin-top:4px;">'+(live?'Plant is aging (if Maintenance Aging is also ON) and System Lead may call at random, unannounced.':'Everything is frozen \u2014 no outage/maintenance aging progresses and System Lead will not call while paused.')+'</div>'+
  '</div>'+
  '<button id="liveToggleBtn" style="display:block;width:100%;background:'+(live?'#5c1717':'#1c3a1c')+';border:1px solid '+(live?'#883030':'#3a7a3a')+';color:#fff;border-radius:6px;padding:12px;cursor:pointer;font:700 14px inherit;margin-bottom:14px;">'+(live?'\u23f8\ufe0f Pause everything':'\u25b6\ufe0f Resume (go Live)')+'</button>'+
  (live?'<div style="font-size:11.5px;color:#9aa6b2;text-align:center;">Next possible System Lead call in about '+nextMin.toFixed(0)+' min (random \u2014 10\u201330 min apart, resets after each call).</div>':'')+
  '<hr style="border-color:#2a3542;margin:16px 0;">'+
  '<div style="font-size:11px;color:#6a7684;">This is the master switch for "the plant runs on its own." The separate Maintenance Aging toggle in the top bar still controls whether scheduled/PM outages age at all \u2014 Pause here freezes them too, on top of that. Reset from a System Lead call itself doesn\u2019t need Pause \u2014 just click "End call" in Command Center \u2192 System Lead.</div>';
 var tb=document.getElementById('liveToggleBtn');
 if(tb)tb.addEventListener('click',function(){PLANT.simLive=!PLANT.simLive;updateLiveBtn();renderLivePanel();});
}
function updateLiveBtn(){
 var btn=document.getElementById('cfLiveBtn'); if(!btn)return;
 if(PLANT.simLive){btn.textContent='\u25b6\ufe0f LIVE';btn.style.background='#1c3a1c';btn.style.color='#bfffbf';btn.style.borderColor='#3a7a3a';}
 else{btn.textContent='\u23f8\ufe0f PAUSED';btn.style.background='#3a1c1c';btn.style.color='#ffbfa0';btn.style.borderColor='#7a3a2a';}
}
function openLivePanel(){document.getElementById('livePanel').style.display='block';renderLivePanel();}
function closeLivePanel(){document.getElementById('livePanel').style.display='none';}
document.getElementById('liveClose').addEventListener('click',closeLivePanel);
document.getElementById('livePanel').addEventListener('click',function(e){if(e.target===this)closeLivePanel();});
document.getElementById('cfLiveBtn').addEventListener('click',openLivePanel);
updateLiveBtn();
/* ═══ Simulation Speed popup (beside Live/Pause) -- cycles 1x/2x/5x/10x real time,
   back to 1x. 1x=teal (matches normal LIVE styling), 2x=yellow, 5x=orange, 10x=red,
   for at-a-glance recognition from across a room the same way the LIVE button already
   works. See PLANT.tick()'s simSeconds line and the ctTick/eqtTimer loops above for
   the actual speed-up mechanism. ═══ */
if(PLANT.simSpeed==null)PLANT.simSpeed=1;
var SPEED_STEPS=[1,2,5,10];
var SPEED_COLORS={1:{bg:'#1c3a3a',fg:'#bfffff',bd:'#3a7a7a'},2:{bg:'#3a3a1c',fg:'#ffffbf',bd:'#7a7a3a'},5:{bg:'#3a2a10',fg:'#ffd280',bd:'#7a5a20'},10:{bg:'#3a1c1c',fg:'#ffbfa0',bd:'#7a3a2a'}};
function updateSpeedBtn(){
 var btn=document.getElementById('cfSpeedBtn'); if(!btn)return;
 var sp=PLANT.simSpeed||1, c=SPEED_COLORS[sp]||SPEED_COLORS[1];
 btn.textContent='\u23e9 '+sp+'x '+(sp===1?'REAL TIME':'SPEED');
 btn.style.background=c.bg;btn.style.color=c.fg;btn.style.borderColor=c.bd;
}
function renderSpeedPanel(){
 var body=document.getElementById('speedBody'); if(!body)return;
 var sp=PLANT.simSpeed||1;
 var html='<div style="text-align:center;margin-bottom:16px;">'+
  '<div style="font-size:15px;font-weight:700;color:'+(SPEED_COLORS[sp]||SPEED_COLORS[1]).fg+';">Currently running at '+sp+'x'+(sp===1?' (real time)':'')+'</div>'+
  '<div style="font-size:11.5px;color:#8a97a4;margin-top:4px;">Speeds up how fast pressures, temperatures, levels and weather move toward their targets, and how fast simulated time (ESD trip clock, weather system) advances. Click a speed below, or click the button again to cycle.</div>'+
  '</div>'+
  '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">';
 SPEED_STEPS.forEach(function(s){
  var c=SPEED_COLORS[s];
  var active=(s===sp);
  html+='<button data-speed="'+s+'" style="padding:14px;border-radius:8px;cursor:pointer;font:700 15px inherit;background:'+(active?c.bg:'#161c24')+';color:'+(active?c.fg:'#8a97a4')+';border:2px solid '+(active?c.bd:'#2a3542')+';">'+s+'x'+(active?' \u2713':'')+'</button>';
 });
 html+='</div>'+
  '<hr style="border-color:#2a3542;margin:16px 0;">'+
  '<div style="font-size:11px;color:#6a7684;">This is independent of the Outages panel\u2019s own speed selector, which only controls scheduled/PM outage aging. This control affects the whole plant\u2019s live physics tick rate and simulated clock.</div>';
 body.innerHTML=html;
 body.querySelectorAll('[data-speed]').forEach(function(b){
  b.addEventListener('click',function(){
   PLANT.simSpeed=parseInt(b.getAttribute('data-speed'),10)||1;
   updateSpeedBtn();renderSpeedPanel();
  });
 });
}
function openSpeedPanel(){document.getElementById('speedPanel').style.display='block';renderSpeedPanel();}
function closeSpeedPanel(){document.getElementById('speedPanel').style.display='none';}
document.getElementById('speedClose').addEventListener('click',closeSpeedPanel);
document.getElementById('speedPanel').addEventListener('click',function(e){if(e.target===this)closeSpeedPanel();});
document.getElementById('cfSpeedBtn').addEventListener('click',function(){
 /* Single click on the toolbar button itself also cycles speed forward (1\u21922\u21925\u219210\u21921)
    without needing to open the popup first -- matches the request that clicking the
    button cycles speed; opening the popup (via a second/held interaction) is available
    for picking a specific speed directly. Simplest reliable version: click = open panel
    AND advance one step, so a single click both shows current state and moves it along. */
 var idx=SPEED_STEPS.indexOf(PLANT.simSpeed||1);
 PLANT.simSpeed=SPEED_STEPS[(idx+1)%SPEED_STEPS.length];
 updateSpeedBtn();
 openSpeedPanel();
});
updateSpeedBtn();
