  var grid=el('div',null,host);grid.style.cssText='display:grid;grid-template-columns:1fr;gap:8px;';source.facts.forEach(function(f){var d=el('details',null,grid);d.style.cssText='padding:9px;border:1px solid #304655;border-radius:5px;';el('summary',f.location,d);el('p',f.text,d);el('small',f.status,d);});el('h3','Pending / intentionally simplified',host);source.pending.forEach(function(t){el('p',t,host);});
