 var ingest=pdfLibIngestFiles;pdfLibIngestFiles=function(fileList,cb,options){var inputs=Array.from(fileList||[]);if(!inputs.length)return ingest(fileList,cb,options);return Promise.all(inputs.map(function(file){if(!(file.type==='application/pdf'||/\.pdf$/i.test(file.name)))return Promise.resolve(file);return cfRefReadFile(file).then(function(data){if(cfRefPayload(data)===source.base64)return null;return file;}).catch(function(){return file;});})).then(function(list){var fresh=list.filter(Boolean);if(fresh.length)return ingest(fresh,cb,options);if(cb)cb();return {added:0,reused:inputs.length,embeddedReused:inputs.length,errors:[]};});};
