 INFO.visual_12hz_v1421={t:'V-1421 - Cold Separator 3D Detail / 12HZ',d:['User-requested visual upgrade. Same location, shell/head/skirt envelope and nozzle anchors. Segmented jacket courses, shallow seams, refined existing west manway, base anchors, clear-side ladder/cage (150-degree model azimuth) and open-grating landing, plus equipment plaque.','All added access/cladding dimensions are schematic artistic details, not manufacturer, P&ID or field/as-built measurements. No new field instruments or process connections.','Schematic checkbox hides new decorative details. Model selection remains V-1421. Process control, liquid behavior and interlocks are not changed.','M2135 Rev10 source record is separate from these unverified cosmetic dimensions. Source design dimensions are not asserted to match the existing display-scale envelope.']};unique(LIB_CATS[libEnsureCategory('Model Update Checks')][1],'visual_12hz_v1421');
 INFO.cf_model_update_12hz={t:'Model Update Checks - 12HZ Cold Separator / XV-6810A / M2135',d:['V-1421 actual mesh upgrade, with positions/nozzles/pipes/control logic retained.','XV-6810A same existing M2045 device gets operator-associated PBV/JEV body-plate metadata; PV-6810A stays separate.','New M2135 hardware records are source-only. Existing matched manual blocks get their readable drawing numbers without duplicate objects.','New drawing arrows for 461/468 and 16x12 rejection-transition discrepancy are explicit review items, not silently altered routing.','No numeric operating/relief setpoints inferred from design pressure or ambiguous notes.','Prior whole-network pipe-contact candidates remain pending; no all-plant zero-clash certification.','Original source-media bytes not bundled. No password, database migration or history reset.'].concat(S.pending)};unique(LIB_CATS[libEnsureCategory('Model Update Checks')][1],'cf_model_update_12hz');
 var oldKnowledge=cf3dDeviceKnowledge12GI;cf3dDeviceKnowledge12GI=function(q){var s=String(q||''),text='';if(/XV[ -]*6810A|J107[ /]*38|181201020|IMG_0640|C-6860/i.test(s))text+=P.source+'\n'+P.specifications.map(function(f){return f.join(': ');}).join('\n')+'\n';if(/M2135|cold sep|V[ -]*1421|LCV[ -]*1421[AB]|TCV[ -]*1421|\b(?:200[0-9]|2017|202[2-9]|203[018]|204[3-9])\b/i.test(s))text+='M2135 SOURCE REVIEW (NOT NEW CONTROLS OR UNPLACED MESHES):\n'+S.facts.map(function(f){return f.text;}).join('\n')+'\n';if(/3D|visual|ladder|cladding|platform/i.test(s)&&/cold sep|V[ -]*1421/i.test(s))text+='12HZ visual cladding/access layout is schematic, with original equipment envelope and piping retained.\n';return text+oldKnowledge(q);};window.CF3DDeviceRegistry.knowledge=cf3dDeviceKnowledge12GI;
