function cfMountSuctionValves12KM(H,S){
 'use strict';
 var out={build:'12KM',pairs:[],updated:[],reused:[],restored:[],errors:[],newPhysicalIdentities:0,pipeRoutesChanged:0,plantWrites:0};
 function arr(p){return Array.isArray(p)?p:p.toArray();}
 function near(a,b){return a.every(function(v,i){return Math.abs(v-b[i])<1e-5;});}
 function station(run,p){var length=0;for(var i=0;i<run.points.length-1;i++){var a=arr(run.points[i]),b=arr(run.points[i+1]),d=b.map(function(v,j){return v-a[j];}),l=Math.hypot.apply(null,d),u=l?d.map(function(v){return v/l;}):[0,0,0],t=p.reduce(function(v,n,j){return v+(n-a[j])*u[j];},0);if(l&&t>=-1e-6&&t<=l+1e-6&&near(p,a.map(function(v,j){return v+u[j]*t;})))return {arc:length+t,leg:i,t:t,length:l};length+=l;}return null;}
 function aliases(r,names){r.aliases=r.aliases||[];names.filter(Boolean).forEach(function(a){if(r.aliases.indexOf(a)<0)r.aliases.push(a);[a,a.toUpperCase().replace(/[^A-Z0-9]/g,'')].forEach(function(k){var owner=H.aliases[k];if(owner&&owner!==r.assetId)throw Error('Ambiguous source alias '+k);H.aliases[k]=r.assetId;});});}
 S.valves.forEach(function(q){try{
  var run=H.runs.find(function(r){return r.key===q.pipeKey&&near(arr(r.points[0]),q.routeStart)&&near(arr(r.points[r.points.length-1]),q.routeEnd);});
  if(!run)throw Error('Retained host route changed: '+q.pipeKey);
  var xv=H.controls.find(function(v){return v.key===q.xvKey;}),pv=H.controls.find(function(v){return v.key===q.pvKey;});
  if(!xv||!pv)throw Error('Existing suction-pair definition missing '+q.unit);
  var xs=station(run,xv.center),ps=station(run,pv.center);
  if(!xs||!ps||xs.arc+xv.half>=ps.arc-pv.half)throw Error('Suction XV/PV order or clearance failed '+q.unit);
  [[xv,q.tag,q.vendorAlias],[pv,q.pvTag,q.vendorPVAlias]].forEach(function(item){
   var v=item[0],tag=item[1],key=v.key,r=H.records[key];if(!r)throw Error('Existing valve record missing '+key);
   var previousTag=r.tag,parts=(H.byKey[key]||[]).filter(function(m){return m.parent&&m.geometry&&!m.isSprite&&!(m.userData||{}).positionPart12KI;});
   var body=parts.find(function(m){return (m.userData||{}).valvePart==='inline-bore';});
   if(!body){delete v.installedSpool;v.tag=tag;H.install(v);parts=(H.byKey[key]||[]).filter(function(m){return m.parent&&m.geometry&&!m.isSprite;});body=parts.find(function(m){return (m.userData||{}).valvePart==='inline-bore';});if(!body)throw Error('No attached inline body after restoration '+tag);out.restored.push(key);}else out.reused.push(key);
   if(!near(arr(body.position),v.center))throw Error('Body and source station disagree '+tag);
   if(!r.geometryHistory12KM)r.geometryHistory12KM={tag:previousTag,referenceRecordOnly:!!r.referenceRecordOnly,modelKey:r.modelKey||null,status:r.status||'',location:r.location||''};
   v.tag=tag;v.aliases=Array.from(new Set((v.aliases||[]).concat([previousTag,item[2],tag]).filter(Boolean)));v.referenceRecordOnly=false;v.packagePending=false;v.identityStatus='OPERATOR_CONFIRMED_TAG_12KM / retained source host';v.placementNote='Retained exact '+q.pipeKey+' station; '+q.tag+' upstream of '+q.pvTag+'. Field coordinates and actuator dimensions remain schematic.';
   r.tag=tag;r.tagConfirmed=true;r.valveNumber=tag;r.referenceRecordOnly=false;r.referenceOnly=false;r.modelKey=key;r.parent=q.owner;r.parentAssetId=q.owner;r.equipment='C-'+q.unit;
   r.location=tag+' on '+q.pipeKey+'; '+(key===q.xvKey?'upstream of '+q.pvTag:'downstream of '+q.tag)+'; retained source-associated schematic station.';
   r.status='SOURCE_HOST_MOUNTED / OPERATOR_TAG_CROSSWALK_12KM';r.point12KM=v.center.slice();r.placement=r.location+' Exact field distances/actuator dimensions remain unverified.';
   r.suctionArrangement12KM={owner:q.owner,upstreamXV:q.tag,downstreamPV:q.pvTag,hostKey:q.pipeKey,center:v.center.slice(),authority:q.basis};
   aliases(r,[key,tag,previousTag,item[2]].concat(v.aliases));
   parts.forEach(function(m){m.userData=m.userData||{};m.userData.controlValveTag=tag;m.userData.sourceMount12KM=true;if(key===q.xvKey&&/^(rotary-body|connection-neck|inline-bore)$/.test(m.userData.valvePart||'')){var mat=m.material&&m.material.clone?m.material.clone():null;if(mat&&mat.color){mat.color.set(0x258c89);m.material=mat;}}});
   H.anchors[key]={top:H.vector(v.center),mid:H.vector(v.center)};
   H.replaceLabel(key,tag,v);H.deviceData[key]=Object.assign({},H.deviceData[key]||{},r);
   out.updated.push({key:key,tag:tag,center:v.center.slice(),pipeKey:q.pipeKey,station:station(run,v.center).arc,bodyParts:parts.length});
  });out.pairs.push({unit:q.unit,xv:q.tag,pv:q.pvTag,host:q.pipeKey,xvStation:xs.arc,pvStation:ps.arc,order:'XV -> retained strainer/line details -> PV -> compressor suction'});
 }catch(e){out.errors.push({unit:q.unit,error:String(e.message||e)});}});return out;
}
function cfPatchSuctionTrace12KM(T,S,allowed){
 'use strict';var out={build:'12KM',hosts:[],errors:[],routeChanges:0},allow=allowed||[];
 S.valves.forEach(function(q){[[q.xvKey,q.tag,q.center,q.vendorAlias],[q.pvKey,q.pvTag,q.pvCenter,q.vendorPVAlias]].forEach(function(a){if(allow.indexOf(a[0])<0)return;
  var c=T.components[a[0]],ri=T.routes.findIndex(function(r){return r.key===q.pipeKey;}),candidates=[];
  if(!c||ri<0){out.errors.push('Missing trace record '+a[1]);return;}
  T.edges.forEach(function(e){if(e.r!==ri)return;[e.a,e.b].forEach(function(n){if(T.nodes[n].every(function(x,j){return Math.abs(x-a[2][j])<1e-5;})&&candidates.indexOf(n)<0)candidates.push(n);});});
  if(candidates.length!==1){out.errors.push('Exact same-route host node missing/ambiguous '+a[1]);return;}
  if(!c.suctionHistory12KM)c.suctionHistory12KM={tag:c.tag,host:c.host||null,modelKey:c.modelKey||null,referenceOnly:!!c.referenceOnly};
  c.tag=a[1];c.modelKey=a[0];c.referenceOnly=false;c.referenceRecordOnly=false;c.host={node:candidates[0],routes:[ri]};c.aliases=Array.from(new Set((c.aliases||[]).concat([a[1],a[3],c.suctionHistory12KM.tag]).filter(Boolean)));c.status='SOURCE_HOST_MOUNTED / OPERATOR_TAG_CROSSWALK_12KM';
  c.aliases.concat([c.key]).forEach(function(alias){[alias,alias.toUpperCase().replace(/[^A-Z0-9]/g,'')].forEach(function(k){if(!T.aliases[k]||T.aliases[k]===a[0])T.aliases[k]=a[0];});});out.hosts.push({key:a[0],tag:a[1],node:candidates[0],route:ri});
 });});T.sourceUpdate12KM=out;return out;
}
var CF_SUCTION_MOUNT_12KM=cfMountSuctionValves12KM({runs:CF3D_PIPE_RUNS,controls:CF3D_CONTROL_VALVES,records:CF3D_DEVICE_RECORDS,deviceData:CF3D_DEVICE_DATA,byKey:byKey,anchors:ANCH,aliases:CF3D_DEVICE_ALIASES,install:cf3dInstallValve,vector:function(a){return V(a[0],a[1],a[2]);},replaceLabel:function(k,t,v){
 sprites.filter(function(s){return s.userData&&s.userData.key===k;}).forEach(function(s){if(s.parent)s.parent.remove(s);var i=picks.indexOf(s);if(i>=0)picks.splice(i,1);});sprites=sprites.filter(function(s){return !(s.userData&&s.userData.key===k);});
 var p=V.apply(null,v.center).addScaledVector(V.apply(null,v.stemDirection||[0,1,0]),v.visualScale*4.45);label(t,p.x,p.y,p.z,.85,k,v.kind==='shutdown'?'#ffab73':'#b6a9ff');
}},CF_SOURCE_12KM);
if(CF_SUCTION_MOUNT_12KM.errors.length)console.error('12KM suction valve geometry',CF_SUCTION_MOUNT_12KM.errors);
/* END 12KM RESIDUE SUCTION VALVE RECONCILIATION */

