  var count=0;function v(j,k){var la=j/6*Math.PI,lo=k/10*Math.PI*2,x=Math.sin(la)*Math.cos(lo),y=Math.cos(la),z=Math.sin(la)*Math.sin(lo);buf.position.push(center.x+rad*x,center.y+rad*y,center.z+rad*z);buf.travel.push((entry.row.reverse?-1:1)*(travel+rad*z));buf.angle.push(lo);buf.phase.push(ph);buf.gravity.push(y);count++;}
