var CF_SOURCE_12KV={"build":"12KV","baseline":"12KU","type":"EXISTING_FEATURE_RESTORATION","referenceKey":"psv_information_gaps_12kv","navigation":"Main toolbar > PSV info needed; also Reference Library > PSV info needed and Whole-model plate audit > PSV info needed. Default view: Still needs information. Search by PSV tag, protected equipment tag/name, area or drawing.","policy":"Read-only live view of the existing canonical PSV/relief registry and field-plate evidence. Do not duplicate equipment, copy new set pressures, clear history, change process logic or treat a modeled body/route as completed field verification.","rules":["Show pending nameplate/serial/test records even when the PSV has a 3D model.","Keep source pressure, plate evidence, identity conflicts, discharge/isolation evidence and model presence separate.","Retain parent-qualified vendor relief identities and unconfirmed tags; never merge sister-unit serials.","PSV-4201 operator correction and PSV-4102 source conflict remain separate in their original records.","Use latest available embedded plate checklist when a general audit row is older or missing; do not rewrite either source.","Browser-only uploads are review candidates and cannot automatically close gaps.","The offline checklist does not include private browser data."],"newDomainFacts":0,"newPhysicalEquipment":0,"newQuizQuestions":0,"batch":{"id":"post_12KT_batch","requestNumber":2,"requestCount":3,"prepared":["12KU - Frick RWF-546E parts reference and practical quiz","12KV - restored PSV information-needed finder"],"status":"TWO_OF_THREE_PREPARED","priorBatch":"12KR + 12KS + 12KT retained","deploymentStatus":"PREPARED_ONLY; no production deployment verified"}};
