 var all=S.newEntries.map(function(f){return f.id;}),cat=C.find(function(c){return c[0]==='OEM Manuals / Ariel JGQ/2 / C-5700';});
 if(!cat){cat=['OEM Manuals / Ariel JGQ/2 / C-5700',[]];C.push(cat);}
